(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("epicurus-letters-e", [{"sp": "HDR", "t": "Επίκουρος Ηροδότῳ χαίρειν"}, {"sp": "N", "t": "Τοῖς μὴ δυναμένοις, ὦ Ἡρόδοτε, ἕκαστα τῶν περὶ φύσεως ἀναγεγραμμένων ἡμῖν ἐξακριβοῦν μηδὲ τὰς μείζους τῶν συντεταγμένων βίβλους διαθρεῖν ἐπιτομὴν τῆς ὅλης πραγματείας εἰς τὸ κατασχεῖν τῶν ὁλοσχερωτάτων δοξῶν τὴν μνήμην ἱκανῶς αὐτοῖς παρεσκεύασα, ἵνα παρ’ ἑκάστους τῶν καιρῶν ἐν τοῖς κυριωτάτοις βοηθεῖν αὑτοῖς δύνωνται, καθ’ ὅσον ἂν ἐφάπτωνται τῆς περὶ φύσεως θεωρίας.", "st": "10.35"}, {"sp": "N", "t": "καὶ τοὺς προβεβηκότας δὲ ἱκανῶς ἐν τῇ τῶν ὅλων ἐπιβλέψει τὸν τύπον τῆς ὅλης πραγματείας τὸν κατεστοιχειωμένον δεῖ μνημονεύειν· τῆς γὰρ ἀθρόας ἐπιβολῆς πυκνὸν δεόμεθα, τῆς δὲ κατὰ μέρος οὐχ ὁμοίως. βαδιστέον μὲν οὖν καὶ ἐπ’ ἐκεῖνα συνεχῶς, ἐν 〈δὲ〉τῇ μνήμῃ τὸ τοσοῦτο ποιητέον, ἀφ’ οὗ ἥ τε κυριωτάτη ἐπιβολὴ ἐπὶ τὰ πράγματα ἔσται καὶ δὴ καὶ τὸ κατὰ μέρος ἀκρίβωμα πᾶν ἐξευρήσεται, τῶν ὁλοσχερωτάτων τύπων εὖ περιειλημμένων καὶ μνημονευομένων· ἐπεὶ καὶ τῷ τετελεσιουργημένῳ τοῦτο κυριώτατον τοῦ παντὸς ἀκριβώματος γίνεται, τὸ ταῖς ἐπιβολαῖς ὀξέως δύνασθαι χρῆσθαι καὶ πρὸς ἁπλᾶ στοιχειώματα καὶ φωνὰς συναγομένοις. οὐ γὰρ οἷόν τε τὸ πύκνωμα τῆς συνεχοῦς τῶν ὅλων περιοδείας εἰδέναι μὴ δυνάμενον διὰ βραχεῶν φωνῶν ἅπαν ἐμπεριλαβεῖν ἐν αὑτῷ τὸ καὶ κατὰ μέρος ἂν ἐξακριβωθέν. ὅθεν δὴ πᾶσι χρησίμης οὔσης τοῖς ᾠκειωμένοις φυσιολογίᾳ τῆς τοιαύτης ὁδοῦ, παρεγγυῶν τὸ συνεχὲς ἐνέργημα ἐν φυσιολογίᾳ καὶ τοιούτῳ μάλιστα ἐγγαληνίζων τῷ βίω ἐποίησά σοι καὶ τοιαύτην τινὰ ἐπιτομὴν καὶ στοιχείωσιν τῶν ὅλων δοξῶν.", "st": "10.36"}, {"sp": "N", "t": "Πρῶτον μὲν οὖν τὰ ὑποτεταγμένα τοῖς φθόγγοις, ὦ Ἡρόδοτε, δεῖ εἰληφέναι, ὅπως ἂν τὰ δοξαζόμενα ἢ ζητούμενα ἢ ἀπορούμενα ἔχωμεν εἰς ταῦτα ἀναγαγόντες ἐπικρίνειν, καὶ μὴ ἄκριτα πάντα ἡμῖν 〈ᾖ〉 εἰς ἄπειρον ἀποδεικνύουσιν ἢ κενοὺς φθόγγους ἔχωμεν· ἀνάγκη γὰρ τὸ πρῶτον ἐννόημα καθ’ ἕκαστον φθόγγον βλέπεσθαι καὶ μηθὲν ἀποδείξεως προσδεῖσθαι, εἴπερ ἕξομεν τὸ ζητούμενον ἢ ἀπορούμενον καὶ δοξαζόμενον ἐφ’ ὃ ἀνάξομεν.", "st": "10.38"}, {"sp": "N", "t": "ἔτι τε καὶ τὰς αἰσθήσεις δεῖ πάντως τηρεῖν καὶ ἁπλῶς τὰς παρούσας ἐπιβολὰς εἴτε διανοίας εἴθ’ ὅτου δήποτε τῶν κριτηρίων. ὁμοίως δὲ καὶ τὰ ὑπάρχοντα πάθη, ὅπως ἂν καὶ τὸ προσμένον καὶ τὸ ἄδηλον ἔχωμεν οἷς σημειωσόμεθα.", "st": "10.38b"}, {"sp": "N", "t": "Ταῦτα δὲ διαλαβόντας 〈δεῖ〉 συνορᾶν ἤδη περὶ τῶν ἀδήλων· πρῶτον μὲν ὅτι οὐδὲν γίνεται ἐκ τοῦ μὴ ὄντος. πᾶν γὰρ ἐκ παντὸς ἐγίνετ’ ἂν σπερμάτων γε οὐθὲν προσδεόμενον. καὶ εἰ ἐφθείρετο δὲ τὸ ἀφανιζόμενον εἰς τὸ μὴ ὄν, πάντα ἂν ἀπωλώλει τὰ πράγματα, οὐκ ὄντων τῶν εἰς ἃ διελύετο. Καὶ μὴν καὶ τὸ πᾶν ἀεὶ τοιοῦτον ἦν οἷον νῦν ἐστι, καὶ ἀεὶ τοιοῦτον ἔσται. οὐθὲν γάρ ἐστιν εἰς ὃ μεταβαλεῖ. παρὰ γὰρ τὸ πᾶν οὐθέν ἐστιν, ὃ ἂν εἰσελθὸν εἰς αὐτὸ τὴν μεταβολὴν ποιήσαιτο.", "st": "10.39"}, {"sp": "N", "t": "Ἀλλὰ μὴν καὶ (τοῦτο καὶ ἐν τῇ Μεγάλῃ ἐπιτομῇ φησι κατ’ ἀρχὴν καὶ ἐν τῇ ᾱ Περὶ φύσεως) τὸ πᾶν ἐστι 〈σώματα καὶ κενόν〉· σώματα μὲν γὰρ ὡς ἔστιν, αὐτὴ ἡ αἴσθησις ἐπὶ πάντων μαρτυρεῖ, καθ’ ἣν ἀναγκαῖον τὸ ἄδηλον τῷ λογισμῷ τεκμαίρεσθαι, ὥσπερ προεῖπον τὸ πρόσθεν· εἰ 〈δὲ〉 μὴ ἦν ὃ κενὸν καὶ χώραν καὶ ἀναφῆ φύσιν ὀνομάζομεν, οὐκ ἂν εἶχε τὰ σώματα ὅπου ἦν οὐδὲ δι’ οὗ ἐκινεῖτο, καθάπερ φαίνεται κινούμενα, παρὰ δὲ ταῦτα οὐθὲν οὐδ’ ἐπινοηθῆναι δύναται οὔτε περιληπτῶς οὔτε ἀναλόγως τοῖς περιληπτοῖς ὡς καθ’ ὅλας φύσεις λαμβανόμενα καὶ μὴ ὡς τὰ τούτων συμπτώματα ἢ συμβεβηκότα λεγόμενα.", "st": "10.40"}, {"sp": "N", "t": "Καὶ μὴν καὶ τῶν (τοῦτο καὶ ἐν τῇ πρώτῃ Περὶ φύσεως καὶ τῇ ῑδ̄ καὶ ῑε̄ καὶ τῇ Μεγάλῃ ἐπιτομῇ) σωμάτων τὰ μέν ἐστι συγκρίσεις, τὰ δ’ ἐξ ὧν αἱ συγκρίσεις πεποίηνται· ταῦτα δέ ἐστιν ἄτομα καὶ ἀμετάβλητα, εἴπερ μὴ μέλλει πάντα εἰς τὸ μὴ ὂν φθαρήσεσθαι, ἀλλ’ ἰσχύοντα ὑπομενεῖν ἐν ταῖς διαλύσεσι τῶν συγκρίσεων πλήρη τὴν φύσιν ὄντα καὶ οὐκ ἔχοντα ὅπῃ ἢ ὅπως διαλυθήσεται. ὥστε τὰς ἀρχὰς ἀτόμους ἀναγκαῖον εἶναι σωμάτων φύσεις.", "st": "10.41"}, {"sp": "N", "t": "Ἀλλὰ μὴν καὶ τὸ πᾶν ἄπειρόν ἐστι. τὸ γὰρ πεπερασμένον ἄκρον ἔχει· τὸ δὲ ἄκρον παρ’ ἕτερόν τι θεωρεῖται· ὥστε οὐκ ἔχον ἄκρον πέρας οὐκ ἔχει πέρας δὲ οὐκ ἔχον ἄπειρον ἂν εἴη καὶ οὐ πεπερασμένον. Καὶ μὴν καὶ τῷ πλήθει τῶν σωμάτων ἄπειρόν ἐστι τὸ πᾶν καὶ τῷ μεγέθει τοῦ κενοῦ. εἴ τε γὰρ ἦν τὸ κενὸν ἄπειρον, τὰ δὲ σώματα ὡρισμένα, οὐθαμοῦ ἂν ἔμενε τὰ σώματα, ἀλλ’ ἐφέρετο κατὰ τὸ ἄπειρον κενὸν διεσπαρμένα, οὐκ ἔχοντα τὰ ὑπερείδοντα καὶ στέλλοντα κατὰ τὰς ἀνακοπάς· εἴ τε τὸ κενὸν ἦν ὡρισμένον, οὐκ ἂν εἶχε τὰ ἄπειρα σώματα ὅπου ἐνέστη.", "st": "10.42"}, {"sp": "N", "t": "Πρός τε τούτοις τὰ ἄτομα τῶν σωμάτων καὶ μεστά, ἐξ ὧν καὶ αἱ συγκρίσεις γίνονται καὶ εἰς ἃ διαλύονται, ἀπερίληπτά ἐστι ταῖς διαφοραῖς τῶν σχημάτων· οὐ γὰρ δυνατὸν γενέσθαι τὰς τοσαύτας διαφορὰς ἐκ τῶν αὐτῶν σχημάτων περιειλημμένων. Καὶ καθ’ ἑκάστην δὲ σχημάτισιν ἁπλῶς ἄπειροί εἰσιν αἱ ὅμοιαι, ταῖς δὲ διαφοραῖς οὐχ ἁπλῶς ἄπειροι ἀλλὰ μόνον ἀπερίληπτοι, (οὐδὲ γάρ φησιν ἐνδοτέρω εἰς ἄπειρον τὴν τομὴν τυγχάνειν.", "st": "10.42b"}, {"sp": "N", "t": "λέγει δέ, ἐπειδὴ αἱ ποιότητες μεταβάλλονται), εἰ μέλλει τις μὴ καὶ τοῖς μεγέθεσιν ἁπλῶς εἰς ἄπειρον αὐτὰς ἐκβάλλειν.", "st": "10.43"}, {"sp": "N", "t": "Κινοῦνταί τε συνεχῶς αἱ ἄτομοι (φησὶ δὲ ἐνδοτέρω καὶ ἰσοταχῶς αὐτὰς κινεῖσθαι τοῦ κενοῦ τὴν εἶξιν ὁμοίαν παρεχομένου καὶ τῇ κουφοτάτῃ καὶ τῇ βαρυτάτῃ) τὸν αἰῶνα, καὶ αἱ μὲν εἰς μακρὰν ἀπ’ ἀλλήλων διιστάμεναι, αἱ δὲ αὐτοῦ τὸν παλμὸν ἴσχουσαι, ὅταν τύχωσι τῇ περιπλοκῇ κεκλειμέναι ἢ στεγαζόμεναι παρὰ τῶν πλεκτικῶν.", "st": "10.43b"}, {"sp": "N", "t": "ἥ τε γὰρ τοῦ κενοῦ φύσις ἡ διορίζουσα ἑκάστην αὐτὴν τοῦτο παρασκευάζει, τὴν ὑπέρεισιν οὐχ οἵα τε οὖσα ποιεῖσθαι· ἥ τε στερεότης ἡ ὑπάρχουσα αὐταῖς κατὰ τὴν σύγκρουσιν τὸν ἀποπαλμὸν ποιεῖ, ἐφ’ ὁπόσον ἂν ἡ περιπλοκὴ τὴν ἀποκατάστασιν ἐκ τῆς συγκρούσεως διδῷ ἀρχὴ δὲ τούτων οὐκ ἔστιν, ἀϊδίων τῶν ἀτόμων οὐσῶν καὶ τοῦ κενοῦ.", "st": "10.44"}, {"sp": "N", "t": "(φησὶ δ’ ἐνδοτέρω μηδὲ ποιότητά τινα περὶ τὰς ἀτόμους εἶναι πλὴν σχήματος καὶ μεγέθους καὶ βάρους· τὸ δὲ χρῶμα παρὰ τὴν θέσιν τῶν ἀτόμων ἀλλάττεσθαι ἐν ταῖς Δώδεκα στοιχειώσεσί φησι. πᾶν τε μέγεθος μὴ εἶναι περὶ αὐτάς· οὐδέποτε γοῦν ἄτομος ὤφθη αἰσθήσει.) Ἡ τοσαύτη δὴ φωνὴ τούτων πάντων μνημονευομένων τὸν ἱκανὸν τύπον ὑποβάλλει 〈ταῖς περὶ〉 τῆς τῶν ὄντων φύσεως ἐπινοίαις.", "st": "10.45"}, {"sp": "N", "t": "Ἀλλὰ μὴν καὶ κόσμοι ἄπειροί εἰσιν, οἵ θ’ ὅμοιοι τούτῳ καὶ ἀνόμοιοι. αἵ τε γὰρ ἄτομοι ἄπειροι οὖσαι, ὡς ἄρτι ἀπεδείχθη, φέρονται καὶ πορρωτάτω. οὐ γὰρ κατανήλωνται αἱ τοιαῦται ἄτομοι, ἐξ ὧν ἂν γένοιτο κόσμος ἢ ὑφ’ ὧν ἂν ποιηθείη, οὔτ’ εἰς ἕνα οὔτ’ εἰς πεπερασμένους, οὔθ’ ὅσοι τοιοῦτοι οὔθ’ ὅσοι διάφοροι τούτοις. ὥστε οὐδὲν τὸ ἐμποδοστατῆσόν ἐστι πρὸς τὴν ἀπειρίαν τῶν κόσμων.", "st": "10.45b"}, {"sp": "N", "t": "Καὶ μὴν καὶ τύποι ὁμοιοσχήμονες τοῖς στερεμνίοις εἰσί, λεπτότησιν ἀπέχοντες μακρὰν τῶν φαινομένων. οὔτε γὰρ συστάσεις ἀδυνατοῦσιν ἐν τῷ περιέχοντι γίνεσθαι τοιαῦται οὔτ’ ἐπιτηδειότητες πρὸς κατεργασίας τῶν κοιλωμάτων καὶ λεπτοτήτων [γίνεσθαι], οὔτε ἀπόρροιαι τὴν ἑξῆς θέσιν καὶ βάσιν διατηροῦσαι, ἥνπερ καὶ ἐν τοῖς στερεμνίοις εἶχον· τούτους δὲ τοὺς τύπους εἴδωλα προσαγορεύομεν. καὶ μὴν καὶ ἡ διὰ τοῦ κενοῦ φορὰ κατὰ μηδεμίαν ἀπάντησιν τῶν ἀντικοψάντων γινομένη πᾶν μῆκος περιληπτὸν ἐν ἀπερινοήτῳ χρόνῳ συντελεῖ. βράδους γὰρ καὶ τάχους ἀντικοπὴ καὶ οὐκ ἀντικοπὴ ὁμοίωμα λαμβάνει. οὐ μὴν οὐδ’ ἅμα κατὰ τοὺς διὰ λόγου θεωρητοὺς χρόνους αὐτὸ τὸ φερόμενον σῶμα ἐπὶ τοὺς πλείους τόπους ἀφικνεῖται — ἀδιανόητον γὰρ —, καὶ τοῦτο συναφικνούμενον ἐν αἰσθητῷ χρόνῳ ὅθεν δήποθεν τοῦ ἀπείρου οὐκ ἐξ οὗ ἂν περιλάβωμεν τὴν φορὰν τόπου ἔσται ἀφιστάμενον· ἀντικοπῇ γὰρ ὅμοιον ἔσται, κἂν μέχρι τοσούτου τὸ τάχος τῆς φορᾶς μὴ ἀντικοπὲν καταλίπωμεν.", "st": "10.46"}, {"sp": "N", "t": "χρήσιμον δὴ καὶ τοῦτο κατασχεῖν τὸ στοιχεῖον. εἶθ’ ὅτι τὰ εἴδωλα ταῖς λεπτότησιν ἀνυπερβλήτοις κέχρηται, οὐθὲν ἀντιμαρτυρεῖ τῶν φαινομένων· ὅθεν καὶ τάχη ἀνυπέρβλητα ἔχει, πάντα πόρον σύμμετρον ἔχοντα πρὸς τὸ ἀπείροις αὐτῶν μηθὲν ἀντικόπτειν ἢ ὀλίγα ἀντικόπτειν, πολλαῖς δὲ καὶ ἀπείροις εὐθὺς ἀντικόπτειν τι.", "st": "10.46b"}, {"sp": "N", "t": "πρός τε τούτοις, ὅτι ἡ γένεσις τῶν εἰδώλων ἅμα νοήματι συμβαίνει. καὶ γὰρ ῥεῦσις ἀπὸ τῶν σωμάτων τοῦ ἐπιπολῆς συνεχής, οὐκ ἐπίδηλος σημειώσει διὰ τὴν ἀνταναπλήρωσιν, σῴζουσα τὴν ἐπὶ τοῦ στερεμνίου θέσιν καὶ τάξιν τῶν ἀτόμων ἐπὶ πολὺν χρόνον, εἰ καὶ ἐνίοτε συγχεομένη ὑπάρχει, καὶ συστάσεις ἐν τῷ περιέχοντι ὀξεῖαι διὰ τὸ μὴ δεῖν κατὰ βάθος τὸ συμπλήρωμα γίνεσθαι, καὶ ἄλλοι δὲ τρόποι τινὲς γεννητικοὶ τῶν τοιούτων φύσεών εἰσιν.", "st": "10.48"}, {"sp": "N", "t": "οὐθὲν γὰρ τούτων ἀντιμαρτυρεῖ〈ται〉 ταῖς αἰσθήσεσιν, ἂν βλέπῃ τις, τίνα τρόπον τὰς ἐναργείας [ἵνα] καὶ τὰς συμπαθείας ἀπὸ τῶν ἔξωθεν πρὸς ἡμᾶς ἀνοίσει. Δεῖ δὲ καὶ νομίζειν ἐπεισιόντος τινὸς ἀπὸ τῶν ἔξωθεν τὰς μορφὰς ὁρᾶν ἡμᾶς καὶ διανοεῖσθαι· οὐ γὰρ ἂν ἐναποσφραγίσαιτο τὰ ἔξω τὴν ἑαυτῶν φύσιν τοῦ τε χρώματος καὶ τῆς μορφῆς διὰ τοῦ ἀέρος τοῦ μεταξὺ ἡμῶν τε κἀκείνων, οὐδὲ διὰ τῶν ἀκτίνων ἢ ὧν δήποτε ῥευμάτων ἀφ’ ἡμῶν πρὸς ἐκεῖνα παραγινομένων, οὕτως ὡς τύπων τινῶν ἐπεισιόντων ἡμῖν ἀπὸ τῶν πραγμάτων ὁμοχρόων τε καὶ ὁμοιομόρφων κατὰ τὸ ἐναρμόττον μέγεθος εἰς τὴν ὄψιν ἢ τὴν διάνοιαν, ὠκέως ταῖς φοραῖς χρωμένων, εἶτα διὰ ταύτην τὴν αἰτίαν τοῦ ἑνὸς καὶ συνεχοῦς τὴν φαντασίαν ἀποδιδόντων καὶ τὴν συμπάθειαν ἀπὸ τοῦ ὑποκειμένου σῳζόντων κατὰ τὸν ἐκεῖθεν σύμμετρον ἐπερεισμὸν ἐκ τῆς κατὰ βάθος ἐν τῷ στερεμνίῳ τῶν ἀτόμων πάλσεως. καὶ ἣν ἂν λάβωμεν φαντασίαν ἐπιβλητικῶς τῇ διανοίᾳ ἢ τοῖς αἰσθητηρίοις εἴτε μορφῆς εἴτε συμβεβηκότων, μορφή ἐστιν αὕτη τοῦ στερεμνίου, γινομένη κατὰ τὸ ἑξῆς πύκνωμα ἢ ἐγκατάλειμμα τοῦ εἰδώλου·", "st": "10.49"}, {"sp": "N", "t": "τὸ δὲ ψεῦδος καὶ τὸ διημαρτημένον ἐν τῷ προσδοξαζομένῳ ἀεί ἐστιν. (... ἐπιμαρτυρηθήσεσθαι ἢ μὴ ἀντιμαρτυρηθήσεσθαι, εἶτ’ οὐκ ἐπιμαρτυρουμένου 〈ἢ ἀντιμαρτυρουμένου〉 κατά τινα κίνησιν ἐν ἡμῖν αὐτοῖς συνημμένην τῇ φανταστικῇ ἐπιβολῇ, διάληψιν δὲ ἔχουσαν, καθ’ ἣν τὸ ψεῦδος γίνεται.) ἥ τε γὰρ ὁμοιότης τῶν φαντασμῶν οἱονεὶ ἐν εἰκόνι λαμβανομένων ἢ καθ’ ὕπνους γινομένων ἢ κατ’ ἄλλας τινὰς ἐπιβολὰς τῆς διανοίας ἢ τῶν λοιπῶν κριτηρίων οὐκ ἄν ποτε ὑπῆρχε τοῖς οὖσί τε καὶ ἀληθέσι προσαγορευομένοις, εἰ μὴ ἦν τινα καὶ ταῦτα πρὸς ἃ βάλλομεν· τὸ δὲ διημαρτημένον οὐκ ἂν ὑπῆρχεν, εἰ μὴ ἐλαμβάνομεν καὶ ἄλλην τινὰ κίνησιν ἐν ἡμῖν αὐτοῖς συνημμένην μὲν 〈τῇ φανταστικῇ ἐπιβολῇ〉, διάληψιν δὲ ἔχουσαν· κατὰ δὲ ταύτην [τὴν συνημμένην τῇ φανταστικῇ ἐπιβολῇ, διάληψιν δὲ ἔχουσαν], ἐὰν μὲν μὴ ἐπιμαρτυρηθῇ ἢ ἀντιμαρτυρηθῇ, τὸ ψεῦδος γίνεται· ἐὰν δὲ ἐπιμαρτυρηθῇ ἢ μὴ ἀντιμαρτυρηθῇ, τὸ ἀληθές.", "st": "10.51"}, {"sp": "N", "t": "καὶ ταύτην οὖν σφόδρα γε δεῖ τὴν δόξαν κατέχειν, ἵνα μήτε τὰ κριτήρια ἀναιρῆται τὰ κατὰ τὰς ἐναργείας μήτε τὸ διημαρτημένον ὁμοίως βεβαιούμενον πάντα συνταράττῃ.", "st": "10.52"}, {"sp": "N", "t": "Ἀλλὰ μὴν καὶ τὸ ἀκούειν γίνεται ῥεύματός τινος φερομένου ἀπὸ τοῦ φωνοῦντος ἢ ἠχοῦντος ἢ ψοφοῦντος ἢ ὅπως δήποτε ἀκουστικὸν πάθος παρασκευάζοντος. τὸ δὲ ῥεῦμα τοῦτο εἰς ὁμοιομερεῖς ὄγκους διασπείρεται, ἅμα τινὰ διασῴζοντας συμπάθειαν πρὸς ἀλλήλους καὶ ἑνότητα ἰδιότροπον, διατείνουσαν πρὸς τὸ ἀποστεῖλαν καὶ τὴν ἐπαίσθησιν τὴν ἐπ’ ἐκείνου ὡς τὰ πολλὰ ποιοῦσαν, εἰ δὲ μή γε, τὸ ἔξωθεν μόνον ἔνδηλον παρασκευάζουσαν· ἄνευ γὰρ ἀναφερομένης τινὸς ἐκεῖθεν συμπαθείας οὐκ ἂν γένοιτο ἡ τοιαύτη ἐπαίσθησις. οὐκ αὐτὸν οὖν δεῖ νομίζειν τὸν ἀέρα ὑπὸ τῆς προιεμένης φωνῆς ἢ καὶ τῶν ὁμογενῶν σχηματίζεσθαι — πολλὴν γὰρ ἔνδειαν ἕξει τοῦτο πάσχων ὑπ’ ἐκείνης —, ἀλλ’ εὐθὺς τὴν γινομένην πληγὴν ἐν ἡμῖν, ὅταν φωνὴν ἀφίωμεν, τοιαύτην ἔκθλιψιν ὄγκων τινῶν ῥεύματος πνευματώδους ἀποτελεστικῶν ποιεῖσθαι, ἣ τὸ πάθος τὸ ἀκουστικὸν ἡμῖν παρασκευάζει.", "st": "10.53"}, {"sp": "N", "t": "Καὶ μὴν καὶ τὴν ὀσμὴν νομιστέον, ὥσπερ καὶ τὴν ἀκοὴν οὐκ ἄν ποτε οὐθὲν πάθος ἐργάσασθαι, εἰ μὴ ὄγκοι τινὲς ἦσαν ἀπὸ τοῦ πράγματος ἀποφερόμενοι σύμμετροι πρὸς τοῦτο τὸ αἰσθητήριον κινεῖν, οἱ μὲν τοῖοι τεταραγμένως καὶ ἀλλοτρίως, οἱ δὲ τοῖοι ἀταράχως καὶ οἰκείως ἔχοντες.", "st": "10.53b"}, {"sp": "N", "t": "Καὶ μὴν καὶ τὰς ἀτόμους νομιστέον μηδεμίαν ποιότητα τῶν φαινομένων προσφέρεσθαι πλὴν σχήματος καὶ βάρους καὶ μεγέθους καὶ ὅσα ἐξ ἀνάγκης σχήματος συμφυῆ ἐστι. ποιότης γὰρ πᾶσα μεταβάλλει· αἱ δὲ ἄτομοι οὐδὲν μεταβάλλουσιν, ἐπειδή περ δεῖ τι ὑπομένειν ἐν ταῖς διαλύσεσι τῶν συγκρίσεων στερεὸν καὶ ἀδιάλυτον, ὃ τὰς μεταβολὰς οὐκ εἰς τὸ μὴ ὂν ποιήσεται οὐδ’ ἐκ τοῦ μὴ ὄντος, ἀλλὰ κατὰ μεταθέσεις ἐν πολλοῖς, τινῶν δὲ καὶ προσόδους καὶ ἀφόδους. ὅθεν ἀναγκαῖον τὰ [μὴ] μετατιθέμενα ἄφθαρτα εἶναι καὶ τὴν τοῦ μεταβάλλοντος φύσιν οὐκ ἔχοντα, ὄγκους δὲ καὶ σχηματισμοὺς ἰδίους· ταῦτα γὰρ καὶ ἀναγκαῖον ὑπομένειν. καὶ γὰρ ἐν τοῖς παρ’ ἡμῖν μετασχηματιζομένοις κατὰ τὴν περιαίρεσιν τὸ σχῆμα ἐνυπάρχον λαμβάνεται, αἱ δὲ ποιότητες οὐκ ἐνυπάρχουσαι ἐν τῷ μεταβάλλοντι, ὥσπερ ἐκεῖνο καταλείπεται, ἀλλ’ ἐξ ὅλου τοῦ σώματος ἀπολλύμεναι. ἱκανὰ οὖν τὰ ὑπολειπόμενα ταῦτα τὰς τῶν συγκρίσεων διαφορὰς ποιεῖν, ἐπειδή περ ὑπολείπεσθαί γέ τινα ἀναγκαῖον καὶ 〈μὴ〉 εἰς τὸ μὴ ὂν φθείρεσθαι.", "st": "10.54"}, {"sp": "N", "t": "Ἀλλὰ μὴν οὐδὲ δεῖ νομίζειν πᾶν μέγεθος ἐν ταῖς ἀτόμοις ὑπάρχειν, ἵνα μὴ τὰ φαινόμενα ἀντιμαρτυρῇ· παραλλαγὰς δέ τινας μεγεθῶν νομιστέον εἶναι. βέλτιον γὰρ καὶ τούτου προσόντος τὰ κατὰ τὰ πάθη καὶ τὰς αἰσθήσεις γινόμενα ἀποδοθήσεται. πᾶν δὲ μέγεθος ὑπάρχειν οὔτε χρήσιμόν ἐστι πρὸς τὰς τῶν ποιοτήτων διαφοράς, ἀφῖχθαί τε ἅμ’ ἔδει καὶ πρὸς ἡμᾶς ὁρατὰς ἀτόμους·", "st": "10.56"}, {"sp": "N", "t": "ὃ οὐ θεωρεῖται γινόμενον οὔθ’ ὅπως ἂν γένοιτο ὁρατὴ ἄτομος ἔστιν ἐπινοῆσαι. Πρὸς δὲ τούτοις οὐ δεῖ νομίζειν ἐν τῷ ὡρισμένῳ σώματι ἀπείρους ὄγκους εἶναι οὐδ’ ὁπηλίκους οὖν. ὥστε οὐ μόνον τὴν εἰς ἄπειρον τομὴν ἐπὶ τοὔλαττον ἀναιρετέον, ἵνα μὴ πάντα ἀσθενῆ ποιῶμεν κἀν ταῖς περιλήψεσι τῶν ἀθρόων εἰς τὸ μὴ ὂν ἀναγκαζώμεθα τὰ ὄντα θλίβοντες καταναλίσκειν, ἀλλὰ καὶ τὴν μετάβασιν μὴ νομιστέον γίνεσθαι ἐν τοῖς ὡρισμένοις εἰς ἄπειρον μηδ’ ἐ〈πὶ〉 τοὔλαττον. οὔτε γὰρ ὅπως, ἐπειδὰν ἅπαξ τις εἴπῃ ὅτι ἄπειροι ὄγκοι ἔν τινι ὑπάρχουσιν ἢ ὁπηλίκοι οὖν, ἔστι νοῆσαι· πῶς τ’ ἂν ἔτι τοῦτο πεπερασμένον εἴη τὸ μέγεθος; πηλίκοι γάρ τινες δῆλον ὡς οἱ ἄπειροί εἰσιν ὄγκοι· καὶ οὗτοι [ἐξ ὧν] ὁπηλίκοι ἄν ποτε ὦσιν, ἄπειρον ἂν ἦν καὶ τὸ μέγεθος. ἄκρον τε ἔχοντος τοῦ πεπερασμένου διαληπτόν, εἰ μὴ καὶ καθ’ ἑαυτὸ θεωρητόν, οὐκ ἔστι μὴ οὐ καὶ τὸ ἑξῆς τούτου τοιοῦτον νοεῖν καὶ οὕτω κατὰ τὸ ἑξῆς εἰς τοὔμπροσθεν βαδίζοντα εἰς τὸ ἄπειρον ὑπάρχειν καὶ τὸ τοιοῦτον ἀφικνεῖσθαι τῇ ἐννοίᾳ.", "st": "10.57"}, {"sp": "N", "t": "τό τε ἐλάχιστον τὸ ἐν τῇ αἰσθήσει δεῖ κατανοεῖν ὅτι οὔτε τοιοῦτόν ἐστιν οἷον τὸ τὰς μεταβάσεις ἔχον οὔτε πάντῃ πάντως ἀνόμοιον, ἀλλ’ ἔχον μέν τινα κοινότητα τῶν μεταβατῶν, διάληψιν δὲ μερῶν οὐκ ἔχον· ἀλλ’ ὅταν διὰ τὴν τῆς κοινότητος προσεμφέρειαν οἰηθῶμεν διαλήψεσθαί τι αὐτοῦ, τὸ μὲν ἐπιτάδε, τὸ δὲ ἐπέκεινα, τὸ ἴσον ἡμῖν δεῖ προσπίπτειν. ἑξῆς τε θεωροῦμεν ταῦτα ἀπὸ τοῦ πρώτου καταρχόμενοι καὶ οὐκ ἐν τῷ αὐτῷ, οὐδὲ μέρεσι μερῶν ἁπτόμενα, ἀλλ’ ἢ ἐν τῇ ἰδιότητι τῇ ἑαυτῶν τὰ μεγέθη καταμετροῦντα, τὰ πλείω πλεῖον καὶ τὰ ἐλάττω ἔλαττον. ταύτῃ τῇ ἀναλογίᾳ νομιστέον καὶ τὸ ἐν τῇ ἀτόμῳ ἐλάχιστον κεχρῆσθαι· μικρότητι γὰρ ἐκεῖνο δῆλον ὡς διαφέρει τοῦ κατὰ τὴν αἴσθησιν θεωρουμένου, ἀναλογίᾳ δὲ τῇ αὐτῇ κέχρηται. ἐπεί περ καὶ ὅτι μέγεθος ἔχει ἡ ἄτομος, κατὰ τὴν ἐνταῦθα ἀναλογίαν κατηγορήσαμεν, μικρόν τι μόνον μακρὰν ἐκβαλόντες.", "st": "10.58"}, {"sp": "N", "t": "ἔτι τε τὰ ἐλάχιστα καὶ ἀμερῆ πέρατα δεῖ νομίζειν τῶν μηκῶν τὸ καταμέτρημα ἐξ αὑτῶν πρώτων τοῖς μείζοσι καὶ ἐλάττοσι παρασκευάζοντα τῇ διὰ λόγου θεωρίᾳ ἐπὶ τῶν ἀοράτων. ἡ γὰρ κοινότης ἡ ὑπάρχουσα αὐτοῖς πρὸς τὰ †ἀμετάβολα ἱκανὴ τὸ μέχρι τούτου συντελέσαι, συμφόρησιν δὲ ἐκ τούτων κίνησιν ἐχόντων οὐχ οἷόν τε γίνεσθαι.", "st": "10.58b"}, {"sp": "N", "t": "Καὶ μὴν καὶ τοῦ ἀπείρου ὡς μὲν ἀνωτάτω ἢ κατωτάτω οὐ δεῖ κατηγορεῖν τὸ ἄνω ἢ κάτω. † εἰς μέντοι τὸ ὑπὲρ κεφαλῆς, ὅθεν ἂν στῶμεν, εἰς ἄπειρον ἄγειν †ὂν† μηδέποτε φανεῖσθαι τοῦτο ἡμῖν· ἢ τὸ ὑποκάτω τοῦ νοηθέντος εἰς ἄπειρον ἅμα ἄνω τε εἶναι καὶ κάτω πρὸς τὸ αὐτό†· τοῦτο γὰρ ἀδύνατον διανοηθῆναι.", "st": "10.60"}, {"sp": "N", "t": "ὥστε ἔστι μίαν λαβεῖν φορὰν τὴν ἄνω νοουμένην εἰς ἄπειρον καὶ μίαν τὴν κάτω, ἂν καὶ μυριάκις πρὸς τοὺς πόδας τῶν ἐπάνω τὸ παρ’ ἡμῶν φερόμενον 〈εἰς〉 τοὺς ὑπὲρ κεφαλῆς ἡμῶν τόπους ἀφικνῆται ἢ ἐπὶ τὴν κεφαλὴν τῶν ὑποκάτω τὸ παρ’ ἡμῶν κάτω φερόμενον· ἡ γὰρ ὅλη φορὰ οὐθὲν ἧττον ἑκατέρα ἑκατέρᾳ ἀντικειμένη ἐπ’ ἄπειρον νοεῖται.", "st": "10.60b"}, {"sp": "N", "t": "Καὶ μὴν καὶ ἰσοταχεῖς ἀναγκαῖον τὰς ἀτόμους εἶναι, ὅταν διὰ τοῦ κενοῦ εἰσφέρωνται μηθενὸς ἀντικόπτοντος. οὔτε γὰρ τὰ βαρέα θᾶττον οἰσθήσεται τῶν μικρῶν καὶ κούφων, ὅταν γε δὴ μηδὲν ἀπαντᾷ αὐτοῖς· οὔτε τὰ μικρὰ τῶν μεγάλων, πάντα πόρον σύμμετρον ἔχοντα, ὅταν μηθὲν μηδὲ ἐκείνοις ἀντικόπτῃ· οὔθ’ ἡ ἄνω οὔθ’ ἡ εἰς τὸ πλάγιον διὰ τῶν κρούσεων φορά, οὔθ’ ἡ κάτω διὰ τῶν ἰδίων βαρῶν. ἐφ’ ὁπόσον γὰρ ἂν κατίσχῃ ἑκάτερον, ἐπὶ τοσοῦτον ἅμα νοήματι τὴν φορὰν σχήσει, ἕως ἀντικόψῃ ἢ ἔξωθεν ἢ ἐκ τοῦ ἰδίου βάρους πρὸς τὴν τοῦ πλήξαντος δύναμιν.", "st": "10.61"}, {"sp": "N", "t": "Ἀλλὰ μὴν καὶ κατὰ τὰς συγκρίσεις θάττων ἑτέρα ἑτέρας ῥηθήσεται τῶν ἀτόμων ἰσοταχῶν οὐσῶν, τῷ ἐφ’ ἕνα τόπον φέρεσθαι τὰς ἐν τοῖς ἀθροίσμασιν ἀτόμους [καὶ] κατὰ τὸν ἐλάχιστον συνεχῆ χρόνον, εἰ 〈καὶ〉 μὴ ἐφ’ ἕνα κατὰ τοὺς λόγῳ θεωρητοὺς χρόνους· ἀλλὰ πυκνὸν ἀντικόπτουσιν, ἕως ἂν ὑπὸ τὴν αἴσθησιν τὸ συνεχὲς τῆς φορᾶς γίνηται. τὸ γὰρ προσδοξαζόμενον περὶ τοῦ ἀοράτου, ὡς ἄρα καὶ οἱ διὰ λόγου θεωρητοὶ χρόνοι τὸ συνεχὲς τῆς φορᾶς ἕξουσιν, οὐκ ἀληθές ἐστιν ἐπὶ τῶν τοιούτων· ἐπεὶ τό γε θεωρούμενον πᾶν ἢ κατ’ ἐπιβολὴν λαμβανόμενον τῇ διανοίᾳ ἀληθές ἐστι.", "st": "10.62"}, {"sp": "N", "t": "Μετὰ δὲ ταῦτα δεῖ συνορᾶν ἀναφέροντα ἐπὶ τὰς αἰσθήσεις καὶ τὰ πάθη — οὕτω γὰρ ἡ βεβαιοτάτη πίστις ἔσται —, ὅτι ἡ ψυχὴ σῶμά ἐστι λεπτομερὲς παρ’ ὅλον τὸ ἄθροισμα παρεσπαρμένον, προσεμφερέστατον δὲ πνεύματι θερμοῦ τινα κρᾶσιν ἔχοντι καὶ πῇ μὲν τούτῳ προσεμφερές, πῇ δὲ τούτῳ ἔστι δέ τι μέρος πολλὴν παραλλαγὴν εἰληφὸς τῇ λεπτομερείᾳ καὶ αὐτῶν τούτων, συμπαθὲς δὲ τούτῳ μᾶλλον καὶ τῷ λοιπῷ ἀθροίσματι· τοῦτο δὲ πᾶν αἱ δυνάμεις τῆς ψυχῆς δηλοῦσι καὶ τὰ πάθη καὶ αἱ εὐκινησίαι καὶ αἱ διανοήσεις καὶ ὧν στερόμενοι θνήσκομεν. Καὶ μὴν καὶ ὅτι ἔχει ἡ ψυχὴ τῆς αἰσθήσεως τὴν πλείστην αἰτίαν δεῖ κατέχειν· οὐ μὴν εἰλήφει ἂν ταύτην, εἰ μὴ ὑπὸ τοῦ λοιποῦ ἀθροίσματος ἐστεγάζετό πως. τὸ δὲ λοιπὸν ἄθροισμα παρασκευάσαν ἐκείνῃ τὴν αἰτίαν ταύτην μετείληφε καὶ αὐτὸ τοιούτου συμπτώματος παρ’ ἐκείνης, οὐ μέντοι πάντων ὧν ἐκείνη κέκτηται·", "st": "10.63"}, {"sp": "N", "t": "διὸ ἀπαλλαγείσης τῆς ψυχῆς οὐκ ἔχει τὴν αἴσθησιν. οὐ γὰρ αὐτὸ ἐν ἑαυτῷ ταύτην ἐκέκτητο τὴν δύναμιν, ἀλλ’ ἑτέρῳ ἅμα συγγεγενημένῳ αὐτῷ παρεσκεύαζεν, ὃ διὰ τῆς συντελεσθείσης περὶ αὐτὸ δυνάμεως κατὰ τὴν κίνησιν σύμπτωμα αἰσθητικὸν εὐθὺς ἀποτελοῦν ἑαυτῷ ἀπεδίδου κατὰ τὴν ὁμούρησιν καὶ συμπάθειαν καὶ ἐκείνῳ, καθάπερ εἶπον. Διὸ δὴ καὶ ἐνυπάρχουσα ἡ ψυχὴ οὐδέποτε ἄλλου τινὸς μέρους ἀπηλλαγμένου ἀναισθητεῖ· ἀλλ’ ἃ ἂν καὶ ταύτης ξυναπόληται τοῦ στεγάζοντος λυθέντος εἴθ’ ὅλου εἴτε καὶ μέρους τινός, ἐάν περ διαμένῃ, σῴζει τὴν αἴσθησιν.", "st": "10.65"}, {"sp": "N", "t": "τὸ δὲ λοιπὸν ἄθροισμα διαμένον καὶ ὅλον καὶ κατὰ μέρος οὐκ ἔχει τὴν αἴσθησιν ἐκείνου ἀπηλλαγμένου, ὅσον ποτέ ἐστι τὸ συντεῖνον τῶν ἀτόμων πλῆθος εἰς τὴν τῆς ψυχῆς φύσιν. Καὶ μὴν καὶ λυομένου τοῦ ὅλου ἀθροίσματος ἡ ψυχὴ διασπείρεται καὶ οὐκέτι ἔχει τὰς αὐτὰς δυνάμεις οὐδὲ κινεῖται, ὥστε οὐδ’ αἴσθησιν κέκτηται. οὐ γὰρ οἷόν τε νοεῖν αὐτὸ αἰσθανόμενον μὴ ἐν τούτῳ τῷ συστήματι καὶ ταῖς κινήσεσι ταύταις χρώμενον, ὅταν τὰ στεγάζοντα καὶ περιέχοντα μὴ τοιαῦτα ᾖ, ἐν οἷς νῦν οὖσα ἔχει ταύτας τὰς κινήσεις.", "st": "10.66"}, {"sp": "N", "t": "Ἀλλὰ μὴν καὶ τόδε (λέγει ἐν ἄλλοις καὶ ἐξ ἀτόμων αὐτὴν συγκεῖσθαι λειοτάτων καὶ στρογγυλωτάτων, πολλῷ τινι διαφερουσῶν τῶν τοῦ πυρός· καὶ τὸ μέν τι ἄλογον αὐτῆς, ὃ τῷ λοιπῷ παρεσπάρθαι σώματι· τὸ δὲ λογικὸν ἐν τῷ θώρακι, ὡς δῆλον ἔκ τε τῶν φόβων καὶ τῆς χαρᾶς. ὕπνον τε γίνεσθαι τῶν τῆς ψυχῆς μερῶν τῶν παρ’ ὅλην τὴν σύγκρισιν παρεσπαρμένων ἐγκατεχομένων ἢ διαφορουμένων, εἶτα συμπιπτόντων τοῖς † ποργμοῖς. τό τε σπέρμα ἀφ’ ὅλων τῶν σωμάτων φέρεσθαι.)", "st": "10.66b"}, {"sp": "N", "t": "γε δεῖ προσκατανοεῖν, ὅτι τὸ ἀσώματον λέγομεν κατὰ τὴν πλείστην ὁμιλίαν τοῦ ὀνόματος ἐπὶ τοῦ καθ’ ἑαυτὸ νοηθέντος ἄν· καθ’ ἑαυτὸ δὲ οὐκ ἔστι νοῆσαι τὸ ἀσώματον πλὴν τοῦ κενοῦ. τὸ δὲ κενὸν οὔτε ποιῆσαι οὔτε παθεῖν δύναται, ἀλλὰ κίνησιν μόνον δι’ ἑαυτοῦ τοῖς σώμασι παρέχεται. ὥστ’ οἱ λέγοντες ἀσώματον εἶναι τὴν ψυχὴν ματαιΐζουσιν. οὐθὲν γὰρ ἂν ἐδύνατο ποιεῖν οὔτε πάσχειν, εἰ ἦν τοιαύτη· νῦν δ’ ἐναργῶς ἀμφότερα ταῦτα διαλαμβάνομεν περὶ τὴν ψυχὴν τὰ συμπτώματα.", "st": "10.67"}, {"sp": "N", "t": "ταῦτα οὖν πάντα τὰ διαλογίσματα 〈τὰ〉 περὶ ψυχῆς ἀνάγων τις ἐπὶ τὰ πάθη καὶ τὰς αἰσθήσεις, μνημονεύων τῶν ἐν ἀρχῇ ῥηθέντων, ἱκανῶς κατόψεται τοῖς τύποις ἐμπεριειλημμένα εἰς τὸ κατὰ μέρος ἀπὸ τούτων ἐξακριβοῦσθαι βεβαίως.", "st": "10.68"}, {"sp": "N", "t": "Ἀλλὰ μὴν καὶ τὰ σχήματα καὶ τὰ χρώματα καὶ τὰ μεγέθη καὶ τὰ βάρη καὶ ὅσα ἄλλα κατηγορεῖται σώματος ὡσανεὶ συμβεβηκότα ἢ πᾶσιν ἢ τοῖς ὁρατοῖς καὶ κατὰ τὴν αἴσθησιν † αὐτοῖς γνωστοῖς, οὔθ’ ὡς καθ’ ἑαυτάς εἰσι φύσεις δοξαστέον — οὐ γὰρ δυνατὸν ἐπινοῆσαι τοῦτο — οὔτε ὅλως ὡς οὐκ εἰσίν, οὔθ’ ὡς ἕτερ’ ἄττα προσυπάρχοντα τούτῳ ἀσώματα, οὔθ’ ὡς μόρια τούτου, ἀλλ’ ὡς τὸ ὅλον σῶμα καθόλου ἐκ τούτων πάντων τὴν ἑαυτοῦ φύσιν ἔχον ἀίδιον, οὐχ οἷον δὲ εἶναι συμπεφορημένον — ὥσπερ ὅταν ἐξ αὐτῶν τῶν ὄγκων μεῖζον ἄθροισμα συστῇ ἤτοι τῶν πρώτων ἢ τῶν τοῦ ὅλου μεγεθῶν τοῦδε τινὸς ἐλαττόνων —, ἀλλὰ μόνον, ὡς λέγω, ἐκ τούτων ἁπάντων τὴν ἑαυτοῦ φύσιν ἔχον ἀίδιον.", "st": "10.69"}, {"sp": "N", "t": "καὶ ἐπιβολὰς μὲν ἔχοντα ἰδίας πάντα ταῦτά ἐστι καὶ διαλήψεις, συμπαρακολουθοῦντος δὲ τοῦ ἀθρόου καὶ οὐθαμῇ ἀποσχιζομένου, ἀλλὰ κατὰ τὴν ἀθρόαν ἔννοιαν τοῦ σώματος κατηγορίαν εἰληφότος. Καὶ μὴν καὶ τοῖς σώμασι συμπίπτει πολλάκις καὶ οὐκ ἀίδιον παρακολουθεῖν † οὔτ’ ἐν τοῖς ἀοράτοις καὶ οὔτε ἀσώματα †. ὥστε δὴ κατὰ τὴν πλείστην φορὰν τούτῳ τῷ ὀνόματι χρώμενοι φανερὰ ποιοῦμεν τὰ συμπτώματα οὔτε τὴν τοῦ ὅλου φύσιν ἔχειν, ὃ συλλαβόντες κατὰ τὸ ἀθρόον σῶμα προσαγορεύομεν, οὔτε τὴν τῶν ἀίδιον παρακολουθούντων, ὧν ἄνευ σῶμα οὐ δυνατὸν νοεῖσθαι. κατ’ ἐπιβολὰς δ’ ἄν τινας παρακολουθοῦντος τοῦ ἀθρόου ἕκαστα προσαγορευθείη, ἀλλ’ ὅτε δήποτε ἕκαστα συμβαίνοντα θεωρεῖται, οὐκ ἀίδιον τῶν συμπτωμάτων παρακολουθούντων. καὶ οὐκ ἐξελατέον ἐκ τοῦ ὄντος ταύτην τὴν ἐνάργειαν, ὅτι οὐκ ἔχει τὴν τοῦ ὅλου φύσιν ᾧ συμβαίνει ὃ δὴ καὶ σῶμα προσαγορεύομεν, οὐδὲ τὴν τῶν ἀίδιον παρακολουθούντων, οὐδ’ αὖ καθ’ αὑτὰ νομιστέον — οὐδὲ γὰρ τοῦτο διανοητὸν οὔτ’ ἐπὶ τούτων οὔτ’ ἐπὶ τῶν ἀίδιον συμβεβηκότων —, ἀλλ’ ὅπερ καὶ φαίνεται, συμπτώματα πάντα τὰ τοιαῦτα νομιστέον, καὶ οὐκ ἀίδιον παρακολουθοῦντα οὐδ’ αὖ φύσεως καθ’ ἑαυτὰ τάγμα ἔχοντα, ἀλλ’ ὃν τρόπον αὐτὴ ἡ αἴσθησις τὴν ἰδιότητα ποιεῖ, θεωρεῖται.", "st": "10.70"}, {"sp": "N", "t": "Καὶ μὴν καὶ τόδε γε δεῖ προσκατανοῆσαι σφοδρῶς· τὸν γὰρ δὴ χρόνον οὐ ζητητέον ὥσπερ καὶ τὰ λοιπά, ὅσα ἐν ὑποκειμένῳ ζητοῦμεν ἀνάγοντες ἐπὶ τὰς βλεπομένας παρ’ ἡμῖν αὐτοῖς προλήψεις, ἀλλ’ αὐτὸ τὸ ἐνάργημα, καθ’ ὃ τὸν πολὺν ἢ ὀλίγον χρόνον ἀναφωνοῦμεν, συγγενικῶς τοῦτο περιφέροντες, ἀναλογιστέον. καὶ οὔτε διαλέκτους ὡς βελτίους μεταληπτέον, ἀλλ’ αὐταῖς ταῖς ὑπαρχούσαις κατ’ αὐτοῦ χρηστέον, οὔτε ἄλλο τι κατ’ αὐτοῦ κατηγορητέον, ὡς τὴν αὐτὴν οὐσίαν ἔχοντος τῷ ἰδιώματι τούτῳ — καὶ γὰρ τοῦτο ποιοῦσί τινες —, ἀλλὰ μόνον ᾧ συμπλέκομεν τὸ ἴδιον τοῦτο καὶ παραμετροῦμεν, μάλιστα ἐπιλογιστέον. καὶ γὰρ τοῦτο οὐκ ἀποδείξεως προσδεῖται ἀλλ’ ἐπιλογισμοῦ, ὅτι ταῖς ἡμέραις καὶ ταῖς νυξὶ συμπλέκομεν καὶ τοῖς τούτων μέρεσιν, ὡσαύτως δὲ καὶ τοῖς πάθεσι καὶ ταῖς ἀπαθείαις, καὶ κινήσεσι καὶ στάσεσιν, ἴδιόν τι σύμπτωμα περὶ ταῦτα πάλιν αὐτὸ τοῦτο ἐννοοῦντες, καθ’ ὃ χρόνον ὀνομάζομεν.", "st": "10.72"}, {"sp": "N", "t": "(φησὶ δὲ τοῦτο καὶ ἐν τῇ δευτέρᾳ Περὶ φύσεως καὶ ἐν τῇ Μεγάλῃ ἐπιτομῇ.) Ἐπί τε τοῖς προειρημένοις τοὺς κόσμους δεῖ καὶ πᾶσαν σύγκρισιν πεπερασμένην τὸ ὁμοειδὲς τοῖς θεωρουμένοις πυκνῶς ἔχουσαν νομίζειν γεγονέναι ἀπὸ τοῦ ἀπείρου, πάντων τούτων ἐκ συστροφῶν ἰδίων ἀποκεκριμένων καὶ μειζόνων καὶ ἐλαττόνων· καὶ πάλιν διαλύεσθαι πάντα, τὰ μὲν θᾶττον, τὰ δὲ βραδύτερον, καὶ τὰ μὲν ὑπὸ τῶν τοιῶνδε, τὰ δὲ ὑπὸ τῶν τοιῶνδε τοῦτο πάσχοντα.", "st": "10.72b"}, {"sp": "N", "t": "δῆλον οὖν ὡς καὶ * * (〈καὶ ἐν τῇ. Περὶ φύσεως〉 φθαρτούς φησι τοὺς κόσμους, μεταβαλλόντων τῶν μερῶν.", "st": "10.74"}, {"sp": "N", "t": "καὶ ἐν ἄλλοις, τὴν γῆν τῷ ἀέρι ἐποχεῖσθαι.) Ἔτι δὲ τοὺς κόσμους οὔτε ἐξ ἀνάγκης δεῖ νομίζειν ἕνα σχηματισμὸν ἔχοντας, ἀλλὰ * * (καὶ διαφόρους αὐτοὺς ἐν τῇ ῑβ̄ Περὶ φύσεως φησιν·", "st": "10.74b"}, {"sp": "N", "t": "οὓς μὲν γὰρ σφαιροειδεῖς, καὶ ᾠοειδεῖς ἄλλους, καὶ ἀλλοιοσχήμονας ἑτέρους·", "st": "10.74c"}, {"sp": "N", "t": "οὐ μέντοι πᾶν σχῆμα ἔχειν. οὐδὲ ζῷα εἶναι ἀποκριθέντα ἀπὸ τοῦ ἀπείρου.) * * οὐδὲ γὰρ ἂν ἀποδείξειεν οὐδείς, ὡς 〈ἐν〉 μὲν τῷ τοιούτῳ καὶ οὐκ ἂν ἐμπεριελήφθη τὰ τοιαῦτα σπέρματα, ἐξ ὧν ζῷά τε καὶ φυτὰ καὶ τὰ λοιπὰ πάντα 〈τὰ〉 θεωρούμενα συνίσταται, ἐν δὲ τῷ τοιούτῳ οὐκ ἂν ἐδυνήθη. (ὡσαύτως δὲ καὶ ἐντραφῆναι.) τὸν αὐτὸν δὲ τρόπον καὶ ἐπὶ γῆς νομιστέον * *", "st": "10.74d"}, {"sp": "N", "t": "Ἀλλὰ μὴν ὑποληπτέον καὶ τὴν φύσιν πολλὰ καὶ παντοῖα ὑπὸ αὐτῶν τῶν πραγμάτων διδαχθῆναί τε καὶ ἀναγκασθῆναι, τὸν δὲ λογισμὸν τὰ ὑπὸ ταύτης παρεγγυηθέντα ὕστερον ἐπακριβοῦν καὶ προσεξευρίσκειν ἐν μέν τισι θᾶττον, ἐν δέ τισι βραδύτερον καὶ ἐν μέν τισι περιόδοις καὶ χρόνοις [ἀπὸ τῶν ἀπὸ τοῦ ἀπείρου] 〈κατὰ μείζους ἐπιδόσεις〉, ἐν δέ τισι κατ’ ἐλάττους. Ὅθεν καὶ τὰ ὀνόματα ἐξ ἀρχῆς μὴ θέσει γενέσθαι, ἀλλ’ αὐτὰς τὰς φύσεις τῶν ἀνθρώπων καθ’ ἕκαστα ἔθνη ἴδια πασχούσας πάθη καὶ ἴδια λαμβανούσας φαντάσματα ἰδίως τὸν ἀέρα ἐκπέμπειν στελλόμενον ὑφ’ ἑκάστων τῶν παθῶν καὶ τῶν φαντασμάτων, ὡς ἄν ποτε καὶ ἡ παρὰ τοὺς τόπους τῶν ἐθνῶν διαφορὰ ᾖ· ὕστερον δὲ κοινῶς καθ’ ἕκαστα ἔθνη τὰ ἴδια τεθῆναι πρὸς τὸ τὰς δηλώσεις ἧττον ἀμφιβόλους γενέσθαι ἀλλήλοις καὶ συντομωτέρως δηλουμένας· τινὰ δὲ καὶ οὐ συνορώμενα πράγματα εἰσφέροντας τοὺς συνειδότας παρεγγυῆσαί τινας φθόγγους τοὺς ἀναγκασθέντας ἀναφωνῆσαι, τοὺς δὲ τῷ λογισμῷ ἑλομένους κατὰ τὴν πλείστην αἰτίαν οὕτως ἑρμηνεῦσαι.", "st": "10.75"}, {"sp": "N", "t": "Καὶ μὴν ἐν τοῖς μετεώροις φορὰν καὶ τροπὴν καὶ ἔκλειψιν καὶ ἀνατολὴν καὶ δύσιν καὶ τὰ σύστοιχα τούτοις μήτε λειτουργοῦντός τινος νομίζειν δεῖ γίνεσθαι καὶ διατάττοντος ἢ διατάξοντος καὶ ἅμα τὴν πᾶσαν μακαριότητα ἔχοντος μετὰ ἀφθαρσίας — οὐ γὰρ συμφωνοῦσι πραγματεῖαι καὶ φροντίδες καὶ ὀργαὶ καὶ χάριτες μακαριότητι, ἀλλ’ ἐν ἀσθενείᾳ καὶ φόβῳ καὶ προσδεήσει τῶν πλησίον ταῦτα γίνεται —, μήτε αὖ πῦρ ἅμα ὄντα συνεστραμμένον τὴν μακαριότητα κεκτημένα κατὰ βούλησιν τὰς κινήσεις ταύτας λαμβάνειν· ἀλλὰ πᾶν τὸ σέμνωμα τηρεῖν κατὰ πάντα ὀνόματα φερόμενα ἐπὶ τὰς τοιαύτας ἐννοίας, ἐὰν μηδὲν ὑπεναντίον ἐξ αὐτῶν τῷ σεμνώματι δόξῃ· εἰ δὲ μὴ, τὸν μέγιστον τάραχον ἐν ταῖς ψυχαῖς αὐτὴ ἡ ὑπεναντιότης παρασκευάσει. ὅθεν δὴ κατὰ τὰς ἐξ ἀρχῆς ἐναπολήψεις τῶν συστροφῶν τούτων ἐν τῇ τοῦ κόσμου γενέσει δεῖ δοξάζειν καὶ τὴν ἀνάγκην ταύτην καὶ περίοδον συντελεῖσθαι.", "st": "10.77"}, {"sp": "N", "t": "Καὶ μὴν καὶ τὴν ὑπὲρ τῶν κυριωτάτων αἰτίαν ἐξακριβῶσαι φυσιολογίας ἔργον εἶναι δεῖ νομίζειν, καὶ τὸ μακάριον ἐν τῇ περὶ μετεώρων γνώσει ἐνταῦθα πεπτωκέναι καὶ ἐν τῷ τίνες φύσεις αἱ θεωρούμεναι κατὰ τὰ μετέωρα ταυτί, καὶ ὅσα συγγενῆ πρὸς τὴν εἰς τοῦτο ἀκρίβειαν· ἔτι τε οὐ τὸ πλεοναχῶς ἐν τοῖς τοιούτοις εἶναι καὶ τὸ ἐνδεχόμενον καὶ ἄλλως πως ἔχειν, ἀλλ’ ἁπλῶς μὴ εἶναι ἐν ἀφθάρτῳ καὶ μακαρίᾳ φύσει τῶν διάκρισιν ὑποβαλλόντων ἢ τάραχον μηθέν. καὶ τοῦτο καταλαβεῖν τῇ διανοίᾳ ἔστιν ἁπλῶς εἶναι· τὸ δ’ ἐν τῇ ἱστορίᾳ πεπτωκὸς τῆς δύσεως καὶ ἀνατολῆς καὶ τροπῆς καὶ ἐκλείψεως καὶ ὅσα συγγενῆ τούτοις μηθὲν ἔτι πρὸς τὸ μακάριον τῆς γνώσεως συντείνειν, ἀλλ’ ὁμοίως τοὺς φόβους ἔχειν τοὺς ταῦτα κατειδότας, τίνες δ’ αἱ φύσεις ἀγνοοῦντας καὶ τίνες αἱ κυριώταται αἰτίαι, καὶ εἰ μὴ προσῄδεσαν ταῦτα· τάχα δὲ καὶ πλείους, ὅταν τὸ θάμβος ἐκ τῆς τούτων προσκατανοήσεως μὴ δύνηται τὴν λύσιν λαμβάνειν κατὰ τὴν περὶ τῶν κυριωτάτων οἰκονομίαν.", "st": "10.78"}, {"sp": "N", "t": "διὸ δὴ καὶ πλείους αἰτίας εὑρίσκομεν τροπῶν καὶ δύσεων καὶ ἀνατολῶν καὶ ἐκλείψεων καὶ τῶν τοιουτοτρόπων ὥσπερ καὶ ἐν τοῖς κατὰ μέρος γινομένοις, καὶ οὐ δεῖ νομίζειν τὴν ὑπὲρ τούτων χρείαν ἀκρίβειαν μὴ ἀπειληφέναι, ὅση πρὸς τὸ ἀτάραχον καὶ μακάριον ἡμῶν συντείνει. ὥστε παραθεωροῦντας ποσαχῶς παρ’ ἡμῖν τὸ ὅμοιον γίνεται, αἰτιολογητέον ὑπέρ τε τῶν μετεώρων καὶ παντὸς τοῦ ἀδήλου, καταφρονοῦντας τῶν οὔτε 〈τὸ〉 μοναχῶς ἔχον ἢ γινόμενον γνωριζόντων οὔτε τὸ πλεοναχῶς συμβαῖνον, τὴν ἐκ τῶν ἀποστημάτων φαντασίαν παριδόντων, ἔτι τε ἀγνοούντων καὶ ἐν ποίοις οὐκ ἔστιν ἀταρακτῆσαι 〈καὶ ἐν ποίοις ὁμοίως ἀταρακτῆσαι〉. ἂν οὖν οἰώμεθα καὶ ὡδί πως ἐνδεχόμενον αὐτὸ γίνεσθαι [καὶ ἐν ποίοις ὁμοίως ἀταρακτῆσαι], αὐτὸ τὸ ὅτι πλεοναχῶς γίνεται γνωρίζοντες, ὥσπερ κἂν ὅτι ὡδί πως γίνεται εἰδῶμεν, ἀταρακτήσομεν.", "st": "10.80"}, {"sp": "N", "t": "Ἐπὶ δὲ τούτοις ὅλως ἅπασιν ἐκεῖνο δεῖ κατανοεῖν, ὅτι τάραχος ὁ κυριώτατος ταῖς ἀνθρωπίναις ψυχαῖς γίνεται ἐν τῷ ταὐτὰ μακάριά τε δοξάζειν 〈εἶναι〉 καὶ ἄφθαρτα καὶ ὑπεναντίας ἔχειν τούτοις ἅμα βουλήσεις καὶ πράξεις καὶ αἰτίας, καὶ ἐν τῷ αἰώνιόν τι δεινὸν ἢ προσδοκᾶν ἢ ὑποπτεύειν κατὰ τοὺς μύθους, εἴτε καὶ αὐτὴν τὴν ἀναισθησίαν τὴν ἐν τῷ τεθνάναι φοβουμένους ὥσπερ οὖσαν κατ’ αὐτούς, καὶ ἐν τῷ μὴ δόξαις ταῦτα πάσχειν ἀλλ’ ἀλόγῳ γέ τινι παραστάσει, ὅθεν μὴ ὁρίζοντας τὸ δεινὸν τὴν ἴσην ἢ καὶ ἐπιτεταμένην ταραχὴν λαμβάνειν τῷ εἰ καὶ ἐδόξαζον ταῦτα· ἡ δὲ ἀταραξία τῷ τούτων πάντων ἀπολελύσθαι καὶ συνεχῆ μνήμην ἔχειν τῶν ὅλων καὶ κυριωτάτων. Ὅθεν τοῖς πάθεσι προσεκτέον τοῖς παροῦσι καὶ ταῖς αἰσθήσεσι, κατὰ μὲν τὸ κοινὸν ταῖς κοιναῖς, κατὰ δὲ τὸ ἴδιον ταῖς ἰδίαις, καὶ πάσῃ τῇ παρούσῃ καθ’ ἕκαστον τῶν κριτηρίων ἐναργείᾳ. ἂν γὰρ τούτοις προσέχωμεν, τὸ ὅθεν ὁ τάραχος καὶ ὁ φόβος ἐγίνετο ἐξαιτιολογήσομεν ὀρθῶς καὶ ἀπολύσομεν, ὑπέρ τε μετεώρων αἰτιολογοῦντες καὶ τῶν λοιπῶν τῶν ἀεὶ παρεμπιπτόντων, ὅσα φοβεῖ τοὺς λοιποὺς ἐσχάτως.", "st": "10.81"}, {"sp": "N", "t": "Ταῦτά σοι, ὦ Ἡρόδοτε, ἔστι κεφαλαιωδέστατα ὑπὲρ τῆς τῶν ὅλων φύσεως ἐπιτετμημένα· ὥστ’ ἐὰν γένηται οὗτος ὁ λόγος δυνατὸς κατασχεθεὶς μετ’ ἀκριβείας, οἶμαι, ἐὰν μὴ καὶ πρὸς ἅπαντα βαδίσῃ τις τῶν κατὰ μέρος ἀκριβωμάτων, ἀσύμβλητον αὐτὸν πρὸς τοὺς λοιποὺς ἀνθρώπους ἁδρότητα λήψεσθαι. καὶ γὰρ καὶ καθαρὰ ἀφ’ ἑαυτοῦ ποιήσει πολλὰ τῶν κατὰ μέρος ἐξακριβουμένων κατὰ τὴν ὅλην πραγματείαν ἡμῖν, καὶ αὐτὰ ταῦτα ἐν μνήμῃ τιθέμενα συνεχῶς βοηθήσει. τοιαῦτα γάρ ἐστιν, ὥστε καὶ τοὺς κατὰ μέρος ἤδη ἐξακριβοῦντας ἱκανῶς ἢ καὶ τελείως, εἰς τὰς τοιαύτας ἀναλύοντας ἐπιβολὰς τὰς πλείστας τῶν περιοδειῶν ὑπὲρ τῆς ὅλης φύσεως ποιεῖσθαι· ὅσοι δὲ μὴ παντελῶς αὐτῶν τῶν ἀποτελουμένων εἰσίν, ἐκ τούτων καὶ κατὰ τὸν ἄνευ φθόγγων τρόπον τὴν ἅμα νοήματι περίοδον τῶν κυριωτάτων πρὸς γαληνισμὸν ποιοῦνται.", "st": "10.83"}, {"sp": "HDR", "t": "Ἐπίκουρος Πυθοκλεῖ χαίρειν"}, {"sp": "N", "t": "Ἤνεγκέ μοι Κλέων ἐπιστολὴν παρὰ σοῦ, ἐν ᾗ φιλοφρονούμενός τε περὶ ἡμᾶς διετέλεις ἀξίως τῆς ἡμετέρας περὶ σεαυτὸν σπουδῆς, καὶ οὐκ ἀπιθάνως ἐπειρῶ μνημονεύειν τῶν εἰς μακάριον βίον συντεινόντων διαλογισμῶν, ἐδέου τε σεαυτῷ περὶ τῶν μετεώρων σύντομον καὶ εὐπερίγραφον διαλογισμὸν ἀποστεῖλαι, ἵνα ῥᾳδίως μνημονεύῃς· τὰ γὰρ ἐν ἄλλοις ἡμῖν γεγραμμένα δυσμνημόνευτα εἶναι, καίτοι, ὡς ἔφης, συνεχῶς αὐτὰ βαστάζεις.", "st": "10.84"}, {"sp": "N", "t": "ἡμεῖς δὲ ἡδέως τέ σου τὴν δέησιν ἀπεδεξάμεθα καὶ ἐλπίσιν ἡδείαις συνεσχέθημεν. γράψαντες οὖν τὰ λοιπὰ πάντα συντελοῦμεν ἅπερ ἠξίωσας πολλοῖς καὶ ἄλλοις ἐσόμενα χρήσιμα τὰ διαλογίσματα ταῦτα, καὶ μάλιστα τοῖς νεωστὶ φυσιολογίας γνησίου γευομένοις καὶ τοῖς εἰς ἀσχολίας βαθυτέρας τῶν ἐγκυκλίων τινὸς ἐμπεπλεγμένοις. καλῶς δὴ αὐτὰ διάλαβε, καὶ διὰ μνήμης ἔχων ὀξέως αὐτὰ περιόδευε μετὰ τῶν λοιπῶν ὧν ἐν τῇ μικρᾷ ἐπιτομῇ πρὸς Ἡρόδοτον ἀπεστείλαμεν.", "st": "10.85"}, {"sp": "N", "t": "Πρῶτον μὲν οὖν μὴ ἄλλο τι τέλος ἐκ τῆς περὶ μετεώρων γνώσεως εἴτε κατὰ συναφὴν λεγομένων εἴτε αὐτοτελῶς νομίζειν 〈δεῖ〉 εἶναι ἤπερ ἀταραξίαν καὶ πίστιν βέβαιον, καθάπερ καὶ ἐπὶ τῶν λοιπῶν,", "st": "10.85b"}, {"sp": "N", "t": "〈καὶ〉 μήτε τὸ ἀδύνατον [καὶ] παραβιάζεσθαι μήτε ὁμοίαν κατὰ πάντα τὴν θεωρίαν ἔχειν ἢ τοῖς περὶ βίων λόγοις ἢ τοῖς κατὰ τὴν τῶν ἄλλων φυσικῶν προβλημάτων κάθαρσιν, οἷον ὅτι τὸ πᾶν σῶμα καὶ ἀναφὴς φύσις ἐστίν, ἢ ὅτι ἄτομα στοιχεῖα καὶ πάντα τὰ τοιαῦτα, [ἢ] ὅσα μοναχὴν ἔχει τοῖς φαινομένοις συμφωνίαν·", "st": "10.86"}, {"sp": "N", "t": "ὅπερ ἐπὶ τῶν μετεώρων οὐχ ὑπάρχει, ἀλλὰ ταῦτά γε πλεοναχὴν ἔχει καὶ τῆς γενέσεως αἰτίαν καὶ τῆς οὐσίας ταῖς αἰσθήσεσι σύμφωνον κατηγορίαν. οὐ γὰρ κατὰ ἀξιώματα κενὰ καὶ νομοθεσίας φυσιολογητέον, ἀλλ’ ὡς τὰ φαινόμενα ἐκκαλεῖται· οὐ γὰρ ἰδιολογίας καὶ κενῆς δόξης ὁ βίος ἡμῶν ἔχει χρείαν, ἀλλὰ τοῦ ἀθορύβως ἡμᾶς ζῆν.", "st": "10.87"}, {"sp": "N", "t": "πάντα μὲν οὖν γίνεται ἀσείστως κατὰ πάντων κατὰ πλεοναχὸν τρόπον ἐκκαθαιρομένων συμφώνως τοῖς φαινομένοις, ὅταν τις τὸ πιθανολογούμενον ὑπὲρ αὐτῶν δεόντως καταλίπῃ· ὅταν δέ τις τὸ μὲν ἀπολίπῃ, τὸ δὲ ἐκβάλῃ ὁμοίως σύμφωνον ὂν τῷ φαινομένῳ, δῆλον ὅτι καὶ ἐκ παντὸς ἐκπίπτει φυσιολογήματος, ἐπὶ δὲ τὸν μῦθον καταρρεῖ.", "st": "10.87b"}, {"sp": "N", "t": "σημεῖα δ’ ἐπὶ τῶν ἐν τοῖς μετεώροις συντελουμένων φέρει τῶν παρ’ ἡμῖν τινα φαινομένων, ἃ θεωρεῖται ᾗ ὑπάρχει· καὶ οὐ τὰ ἐν τοῖς μετεώροις φαινόμενα· ταῦτα γὰρ ἐνδέχεται πλεοναχῶς γίνεσθαι. τὸ μέντοι φάντασμα ἑκάστου τηρητέον καὶ ἐπὶ τὰ συναπτόμενα τούτῳ διαιρετέον, ἃ οὐκ ἀντιμαρτυρεῖται τοῖς παρ’ ἡμῖν γινομένοις πλεοναχῶς συντελεῖσθαι.", "st": "10.88"}, {"sp": "N", "t": "Κόσμος ἐστὶ περιοχή τις οὐρανοῦ, ἄστρα τε καὶ γῆν καὶ πάντα τὰ φαινόμενα περιέχουσα, ἀποτομὴν ἔχουσα ἀπὸ τοῦ ἀπείρου καὶ [κατα]λήγουσα ἐν πέρατι ἢ ἀραιῷ ἢ πυκνῷ καὶ οὗ λυομένου πάντα τὰ ἐν αὐτῷ σύγχυσιν λήψεται —, [καὶ λήγουσαν] ἢ ἐν περιαγομένῳ ἢ ἐν στάσιν ἔχοντι καὶ στρογγύλην ἢ τρίγωνον ἢ οἵαν δήποτε περιγραφήν· πανταχῶς γὰρ ἐνδέχεται· τῶν γὰρ φαινομένων οὐδὲν ἀντιμαρτυρεῖ 〈ἐν〉 τῷδε τῷ κόσμῳ, ἐν ᾧ λῆγον οὐκ ἔστι καταλαβεῖν. Ὅτι δὲ καὶ τοιοῦτοι κόσμοι εἰσὶν ἄπειροι τὸ πλῆθος ἔστι καταλαβεῖν, καὶ ὅτι καὶ ὁ τοιοῦτος δύνεται κόσμος γίνεσθαι (καὶ ἐν κόσμῳ καὶ μετακοσμίῳ, ὃ λέγομεν μεταξὺ κόσμων διάστημα) ἐν πολυκένῳ τόπῳ καὶ οὐκ ἐν μεγάλῳ εἰλικρινεῖ καὶ κενῷ, καθάπερ τινές φασιν, ἐπιτηδείων τινῶν σπερμάτων ῥυέντων ἀφ’ ἑνὸς κόσμου ἢ μετακοσμίου ἢ ἀπὸ πλειόνων κατὰ μικρὸν προσθέσεις τε καὶ διαρθρώσεις καὶ μεταστάσεις ποιούντων ἐπ’ ἄλλον τόπον, ἐὰν οὕτω τύχῃ, καὶ ἐπαρδεύσεις ἐκ τῶν ἐχόντων ἐπιτηδείως ἕως τελειώσεως καὶ διαμονῆς ἐφ’ ὅσον τὰ ὑποβληθέντα θεμέλια τὴν προσδοχὴν δύναται ποιεῖσθαι.", "st": "10.89"}, {"sp": "N", "t": "οὐ γὰρ ἀθροισμὸν δεῖ μόνον γενέσθαι οὐδὲ δῖνον ἐν ᾧ ἐνδέχεται κόσμον γίνεσθαι κενῷ κατὰ τὸ δοξαζόμενον ἐξ ἀνάγκης, αὔξεσθαί τε, ἕως ἂν ἑτέρῳ προσκρούσῃ, καθάπερ τῶν φυσικῶν καλουμένων φησί τις. τοῦτο γὰρ μαχόμενόν ἐστι τοῖς φαινομένοις.", "st": "10.89b"}, {"sp": "N", "t": "Ἥλιός τε καὶ σελήνη καὶ τὰ λοιπὰ ἄστρα 〈οὐ〉 καθ’ ἑαυτὰ γενόμενα ὕστερον ἐμπεριελαμβάνετο ὑπὸ τοῦ κόσμου καὶ ὅσα γε δὴ σῴζει, ἀλλ’ εὐθὺς διεπλάττετο καὶ αὔξησιν ἐλάμβανεν (ὁμοίως δὲ καὶ γῆ καὶ θάλαττα) κατὰ προσκρίσεις καὶ δινήσεις λεπτομερῶν τινων φύσεων, ἤτοι πνευματικῶν ἢ πυροειδῶν ἢ τὸ συναμφότερον· καὶ γὰρ ταῦτα οὕτως ἡ αἴσθησις ὑποβάλλει.", "st": "10.89c"}, {"sp": "N", "t": "Τὸ δὲ μέγεθος ἡλίου τε 〈καὶ σελήνης〉 καὶ τῶν λοιπῶν ἄστρων κατὰ μὲν τὸ πρὸς ἡμᾶς τηλικοῦτόν ἐστιν ἡλίκον φαίνεται.", "st": "10.91"}, {"sp": "N", "t": "(τοῦτο καὶ ἐν τῇ ιᾱ Περὶ φύσεως· εἰ γάρ, φησί, τὸ μέγεθος διὰ τὸ διάστημα ἀποβεβλήκει, πολλῷ μᾶλλον ἂν τὴν χρόαν.) ἄλλο γὰρ τούτῳ συμμετρότερον διάστημα οὐθέν ἐστι·", "st": "10.91b"}, {"sp": "N", "t": "κατὰ δὲ τὸ καθ’ αὑτὸ ἤτοι μεῖζον τοῦ ὁρωμένου ἢ μικρῷ ἔλαττον ἢ τηλικοῦτον (οὐχ ἅμα). οὕτω γὰρ καὶ τὰ παρ’ ἡμῖν πυρὰ ἐξ ἀποστήματος θεωρούμενα κατὰ τὴν αἴσθησιν θεωρεῖται. καὶ πᾶν δὲ τὸ εἰς τοῦτο τὸ μέρος ἔνστημα ῥᾳδίως διαλυθήσεται, ἐάν τις τοῖς ἐναργήμασι προσέχῃ, ὅπερ ἐν τοῖς περὶ φύσεως βιβλίοις δείκνυμεν.", "st": "10.91c"}, {"sp": "N", "t": "Ἀνατολὰς καὶ δύσεις ἡλίου καὶ σελήνης καὶ τῶν λοιπῶν ἄστρων καὶ κατὰ ἄναψιν γίνεσθαι δυνατὸν καὶ κατὰ σβέσιν, τοιαύτης οὔσης περιστάσεως (καὶ καθ’ ἑκατέρους τοὺς τρόπους), ὥστε τὰ προειρημένα ἀποτελεῖσθαι· οὐδὲν γὰρ τῶν φαινομένων ἀντιμαρτυρεῖ. 〈καὶ〉 κατ’ ἐκφάνειάν τε ὑπὲρ γῆς καὶ πάλιν ἐπιπρόσθησιν τὸ προειρημένον δύναιτ’ ἂν συντελεῖσθαι· οὐδὲ γάρ τι τῶν φαινομένων ἀντιμαρτυρεῖ.", "st": "10.92"}, {"sp": "N", "t": "Τάς τε κινήσεις αὐτῶν οὐκ ἀδύνατον μὲν γίνεσθαι κατὰ τὴν τοῦ ὅλου οὐρανοῦ δίνην, ἢ τούτου μὲν στάσιν, αὐτῶν δὲ δίνην κατὰ τὴν ἐξ ἀρχῆς ἐν τῇ γενέσει τοῦ κόσμου ἀνάγκην ἀπογεννηθεῖσαν (ἐπ’ ἀνατολῇ τὰ τῇ θερμασίᾳ...) 〈ἢ καὶ〉 κατά τινα ἐπινέμησιν τοῦ πυρὸς ἀεὶ ἐπὶ τοὺς ἑξῆς τόπους ἰόντος.", "st": "10.93"}, {"sp": "N", "t": "Τροπὰς ἡλίου καὶ σελήνης ἐνδέχεται μὲν γίνεσθαι κατὰ λόξωσιν οὐρανοῦ οὕτω τοῖς χρόνοις κατηναγκασμένου· ὁμοίως δὲ καὶ κατὰ ἀέρος ἀντέξωσιν ἢ καὶ ὕλης ἀεὶ ἐπιτηδείας ἐχομένης ἐμπιπραμένης, τῆς δὲ καταλειπομένης· ἢ καὶ ἐξ ἀρχῆς τοιαύτην δίνην κατειληθῆναι τοῖς ἄστροις τούτοις, ὥσθ’ οἷόν τιν’ ἕλικα κινεῖσθαι. πάντα γὰρ τὰ τοιαῦτα καὶ τὰ τούτοις συγγενῆ οὐθενὶ τῶν ἐναργημάτων διαφωνεῖ, ἐάν τις ἀεὶ ἐπὶ τῶν τοιούτων μερῶν ἐχόμενος τοῦ δυνατοῦ εἰς τὸ σύμφωνον τοῖς φαινομένοις ἕκαστον τούτων δύνηται ἐπανάγειν, μὴ φοβούμενος τὰς ἀνδραποδώδεις ἀστρολόγων τεχνιτείας.", "st": "10.93b"}, {"sp": "N", "t": "Κένωσίς τε σελήνης καὶ πάλιν πλήρωσις καὶ κατὰ στροφὴν τοῦ σώματος τούτου δύναιτ’ ἂν γίνεσθαι καὶ κατὰ σχηματισμοὺς ἀέρος ὁμοίως, ἔτι τε καὶ κατ’ ἐπιπροσθήσεις καὶ κατὰ πάντας τρόπους, καθ’ οὓς καὶ τὰ παρ’ ἡμῖν φαινόμενα ἐκκαλεῖται εἰς τὰς τούτου τοῦ εἴδους ἀποδόσεις, ἐὰν μή τις τὸν μοναχῇ τρόπον κατηγαπηκὼς τοὺς ἄλλους κενῶς ἀποδοκιμάζῃ, οὐ τεθεωρηκὼς τί δυνατὸν ἀνθρώπῳ θεωρῆσαι καὶ τί ἀδύνατον, καὶ διὰ τοῦτο ἀδύνατα θεωρεῖν ἐπιθυμῶν.", "st": "10.94"}, {"sp": "N", "t": "Ἔτι τε ἐνδέχεται 〈μὲν〉 τὴν σελήνην ἐξ ἑαυτῆς ἔχειν τὸ φῶς, ἐνδέχεται δὲ ἀπὸ τοῦ ἡλίου. καὶ γὰρ παρ’ἡμῖν θεωρεῖται πολλὰ μὲν ἐξ ἑαυτῶν ἔχοντα, πολλὰ δὲ ἀφ’ ἑτέρων. καὶ οὐθὲν ἐμποδοστατεῖ τῶν ἐν τοῖς μετεώροις φαινομένων, ἐάν τις τοῦ πλεοναχοῦ τρόπου ἀεὶ μνήμην ἔχῃ καὶ τὰς ἀκολούθους αὐτοῖς ὑποθέσεις ἅμα καὶ αἰτίας συνθεωρῇ καὶ μὴ ἀναβλέπων εἰς τὰ ἀνακόλουθα ταῦτ’ ὀγκοῖ ματαίως καὶ καταρρέπῃ ἄλλοτε ἄλλως ἐπὶ τὸν μοναχὸν τρόπον.", "st": "10.95"}, {"sp": "N", "t": "Ἡ δὲ ἔμφασις τοῦ προσώπου ἐν αὐτῇ δύναται μὲν γίνεσθαι καὶ κατὰ παραλλαγὴν μερῶν καὶ κατ’ ἐπιπρόσθησιν, καὶ ὅσοι ποτ’ ἂν τρόποι θεωροῖντο τὸ σύμφωνον τοῖς φαινομένοις κεκτημένοι. ἐπὶ πάντων γὰρ τῶν μετεώρων τὴν τοιαύτην ἴχνευσιν οὐ προετέον. ἢν γάρ τις ᾖ μαχόμενος τοῖς ἐναργήμασιν, οὐδέποτε μὴ δυνήσεται ἀταραξίας γνησίου μεταλαβεῖν.", "st": "10.96"}, {"sp": "N", "t": "Ἔκλειψις ἡλίου καὶ σελήνης δύναται μὲν γίνεσθαι καὶ κατὰ σβέσιν, καθάπερ καὶ παρὰ ἡμῖν τοῦτο θεωρεῖται γινόμενον· καὶ ἔτι κατ’ ἐπιπρόσθησιν ἄλλων τινῶν, ἢ γῆς ἢ οὐρανοῦ ἢ τινος ἑτέρου τοιούτου. καὶ ὧδε τοὺς οἰκείους ἀλλήλοις τρόπους συνθεωρητέον, καὶ τὰς ἅμα συγκυρήσεις τινῶν ὅτι οὐκ ἀδύνατον γίνεσθαι.", "st": "10.96b"}, {"sp": "N", "t": "(ἐν δὲ τῇ ῑβ̄̄ Περὶ φύσεως ταὐτὰ λέγει καὶ πρός, ἥλιον ἐκλείπειν σελήνης ἐπισκοτούσης, σελήνην δὲ τοῦ τῆς γῆς σκιάσματος, ἀλλὰ καὶ κατ’ ἀναχώρησιν. τοῦτο δὲ καὶ Διογένης ὁ Ἐπικούρειος ἐν τῇ ᾱ τῶν Ἐπιλέκτων.) Ἔτι τε τάξις περιόδου, καθάπερ ἔνια καὶ παρ’ ἡμῖν τῶν τυχόντων γίνεται, λαμβανέσθω·", "st": "10.97"}, {"sp": "N", "t": "καὶ ἡ θεία φύσις πρὸς ταῦτα μηδαμῇ προσαγέσθω, ἀλλ’ ἀλειτούργητος διατηρείσθω καὶ ἐν τῇ πάσῃ μακαριότητι. ὡς εἰ τοῦτο μὴ πραχθήσεται, ἅπασα ἡ τῶν μετεώρων αἰτιολογία ματαία ἔσται, καθάπερ τισὶν ἤδη ἐγένετο οὐ δυνατοῦ τρόπου ἐφαψαμένοις, εἰς δὲ τὸ μάταιον ἐκπεσοῦσι τῷ καθ’ ἕνα τρόπον μόνον οἴεσθαι γίνεσθαι, τοὺς δ’ ἄλλους πάντας τοὺς κατὰ τὸ ἐνδεχόμενον ἐκβάλλειν εἴς τε τὸ ἀδιανόητον φερομένους καὶ τὰ φαινόμενα, ἃ δεῖ σημεῖα ἀποδέχεσθαι, μὴ δυναμένους συνθεωρεῖν.", "st": "10.97b"}, {"sp": "N", "t": "Μήκη νυκτῶν καὶ ἡμερῶν παραλλάττοντα... καὶ παρὰ τὸ ταχείας ἡλίου κινήσεις γίνεσθαι καὶ πάλιν βραδείας 〈καὶ〉 (ὑπὲρ γῆς) παρὰ τὸ μήκη τόπων παραλλάττοντα... (καὶ τόπους τινὰς περαιοῦντα τάχιον), ὡς καὶ παρὰ ἡμῖν (ἢ καὶ βραδύτερον) τινα θεωρεῖται, οἷς συμφώνως δεῖ λέγειν ἐπὶ τῶν μετεώρων. οἱ δὲ τὸ ἓν λαμβάνοντες τοῖς τε φαινομένοις μάχονται καὶ τοῦ ᾗ δυνατὸν ἀνθρώπῳ θεωρῆσαι διαπεπτώκασιν.", "st": "10.98"}, {"sp": "N", "t": "Ἐπισημασίαι δύνανται γίνεσθαι καὶ κατὰ συγκυρήσεις καιρῶν, καθάπερ ἐν τοῖς ἐμφανέσι παρ’ ἡμῖν ζῴοις, καὶ παρ’ ἑτεροιώσεις ἀέρος καὶ μεταβολάς· ἀμφότερα γὰρ ταῦτα οὐ μάχεται τοῖς φαινομένοις. ἐπὶ δὲ ποίοις παρὰ τοῦτο ἢ τοῦτο τὸ αἴτιον γίνεται, οὐκ ἔστι συνιδεῖν.", "st": "10.99"}, {"sp": "N", "t": "Νέφη δύναται γίνεσθαι καὶ συνίστασθαι καὶ παρὰ πιλήσεις ἀέρος πνευμάτων συνώσει καὶ παρὰ περιπλοκὰς ἀλληλούχων ἀτόμων καὶ ἐπιτηδείων εἰς τὸ τοῦτο τελέσαι καὶ κατὰ ῥευμάτων συλλογὴν ἀπό τε γῆς καὶ ὑδάτων· καὶ κατ’ ἄλλους δὲ τρόπους πλείους αἱ τῶν τοιούτων συστάσεις οὐκ ἀδυνατοῦσι συντελεῖσθαι. Ἤδη δ’ ἀπ’ αὐτῶν ᾗ μὲν θλιβομένων, ᾗ δὲ μεταβαλλόντων ὕδατα δύναται συντελεῖσθαι, ἔτι τε (πνεύματα κατὰ ἀποφορὰν ἀπὸ ἐπιτηδείων τόπων) καὶ δι’ ἀέρος κινουμένων, βιαιοτέρας ἐπαρδεύσεως γινομένης ἀπό τινων ἀθροισμάτων ἐπιτηδείων εἰς τὰς τοιαύτας ἐπιπέμψεις.", "st": "10.100"}, {"sp": "N", "t": "Βροντὰς ἐνδέχεται γίνεσθαι καὶ κατὰ πνεύματος ἐν τοῖς κοιλώμασι τῶν νεφῶν ἀνείλησιν, καθάπερ ἐν τοῖς ἡμετέροις ἀγγείοις, καὶ παρὰ πυρὸς πεπνευματωμένου βόμβον ἐν αὐτοῖς, καὶ κατὰ ῥήξεις δὲ νεφῶν καὶ διαστάσεις, καὶ κατὰ παρατρίψεις νεφῶν καὶ †τάξεις πῆξιν εἰληφότων κρυσταλλοειδῆ· καὶ τὸ ὅλον καὶ τοῦτο τὸ μέρος πλεοναχῶς γίνεσθαι λέγειν ἐκκαλεῖται τὰ φαινόμενα.", "st": "10.100b"}, {"sp": "N", "t": "Καὶ ἀστραπαὶ δ’ ὡσαύτως γίνονται κατὰ πλείους τρόπους· καὶ γὰρ κατὰ παράτριψιν καὶ σύγκρουσιν νεφῶν ὁ πυρὸς ἀποτελεστικὸς σχηματισμὸς ἐξολισθαίνων ἀστραπὴν γεννᾷ· καὶ κατ’ ἐκριπισμὸν ἐκ τῶν νεφῶν ὑπὸ πνευμάτων τῶν τοιούτων σωμάτων ἃ τὴν λαμπηδόνα ταύτην παρασκευάζει· καὶ κατ’ ἐκπιασμόν, θλίψεως τῶν νεφῶν γινομένης εἴθ’ ὑπ’ ἀλλήλων εἴθ’ ὑπὸ πνευμάτων· καὶ κατ’ ἐμπερίληψιν δὲ τοῦ ἀπὸ τῶν ἄστρων κατεσπαρμένου φωτός, εἶτα συνελαυνομένου ὑπὸ τῆς κινήσεως νεφῶν τε καὶ πνευμάτων καὶ διεκπίπτοντος διὰ τῶν νεφῶν· ἢ κατὰ διήθησιν 〈διὰ〉 τῶν νεφῶν τοῦ λεπτομερεστάτου φωτὸς (ἢ ἀπὸ τοῦ πυρὸς νέφη συνειλέχθαι καὶ τὰς βροντὰς ἀποτελεῖσθαι) καὶ κατὰ τὴν τούτου κίνησιν· καὶ κατὰ τὴν τοῦ πνεύματος ἐκπύρωσιν τὴν γινομένην διά τε συντονίαν φορᾶς καὶ διὰ σφοδρὰν κατείλησιν· καὶ κατὰ ῥήξεις δὲ νεφῶν ὑπὸ πνευμάτων 〈καὶ〉 ἔκπτωσιν τῶν πυρὸς ἀποτελεστικῶν ἀτόμων καὶ τὸ τῆς ἀστραπῆς φάντασμα ἀποτελουσῶν· καὶ κατ’ ἄλλους δὲ πλείους τρόπους ῥᾳδίως ἔσται καθορᾶν ἐχόμενον ἀεὶ τῶν φαινομένων καὶ τὸ τούτοις ὅμοιον δυνάμενον συνθεωρεῖν.", "st": "10.101"}, {"sp": "N", "t": "Προτερεῖ δὲ ἀστραπὴ βροντῆς ἐν τοιᾷδέ τινι περιστάσει νεφῶν καὶ διὰ τὸ ἅμα τῷ τὸ πνεῦμα ἐμπίπτειν ἐξωθεῖσθαι τὸν ἀστραπῆς ἀποτελεστικὸν σχηματισμόν, ὕστερον δὲ τὸ πνεῦμα ἀνειλούμενον τὸν βόμβον ἀποτελεῖν τοῦτον· καὶ κατ’ ἔμπτωσιν δὲ ἀμφοτέρων ἅμα, τῷ τάχει συντονωτέρῳ κεχρῆσθαι πρὸς ἡμᾶς τὴν ἀστραπήν, ὑστερεῖν δὲ τὴν βροντήν, καθάπερ ἐπ’ ἐνίων ἐξ ἀποστήματος θεωρουμένων καὶ πληγάς τινας ποιουμένων.", "st": "10.103"}, {"sp": "N", "t": "Κεραυνοὺς ἐνδέχεται γίνεσθαι καὶ κατὰ πλείονας πνευμάτων συλλογὰς καὶ κατείλησιν ἰσχυράν τε ἐκπύρωσιν καὶ κατάρρηξιν μέρους καὶ ἔκπτωσιν ἰσχυροτέραν αὐτοῦ ἐπὶ τοὺς κάτω τόπους, τῆς ῥήξεως γινομένης διὰ τὸ τοὺς ἑξῆς τόπους πυκνοτέρους εἶναι διὰ πίλησιν νεφῶν· καὶ κατ’ αὐτὴν δὲ τὴν τοῦ πυρὸς ἔκπτωσιν ἀνειλουμένου, καθὰ καὶ βροντὴν ἐνδέχεται γίνεσθαι, πλείονος γενομένου καὶ πνευματωθέντος ἰσχυρότερον καὶ ῥήξαντος τὸ νέφος διὰ τὸ μὴ δύνασθαι ὑποχωρεῖν εἰς τὰ ἑξῆς, τῷ πίλησιν γίνεσθαι (τὸ μὲν πολὺ πρὸς ὄρος τι ὑψηλόν, ἐν ᾧ μάλιστα κεραυνοὶ πίπτουσιν) ἀεὶ πρὸς ἄλληλα. καὶ κατ’ ἄλλους δὲ τρόπους πλείονας ἐνδέχεται κεραυνοὺς ἀποτελεῖσθαι· μόνον ὁ μῦθος ἀπέστω· ἀπέσται δέ, ἐάν τις καλῶς τοῖς φαινομένοις ἀκολουθῶν περὶ τῶν ἀφανῶν σημειῶται.", "st": "10.104"}, {"sp": "N", "t": "Πρηστῆρας ἐνδέχεται γίνεσθαι καὶ κατὰ κάθεσιν νέφους εἰς τοὺς κάτω τόπους στυλοειδῶς ὑπὸ πνεύματος ἀθρόου ὠσθέντος (καὶ διὰ τοῦ πνεύματος πολλοῦ φερομένου), ἅμα καὶ τὸ νέφος εἰς τὸ πλάγιον ὠθοῦντος τοῦ ἐκτὸς πνεύματος· καὶ κατὰ περίστασιν δὲ πνεύματος εἰς κύκλον, ἀέρος τινὸς ἐπισυνωθουμένου ἄνωθεν, καὶ ῥύσεως πολλῆς πνευμάτων γινομένης καὶ οὐ δυναμένης εἰς τὰ πλάγια διαρρυῆναι διὰ τὴν πέριξ τοῦ ἀέρος πίλησιν. καὶ ἕως μὲν γῆς τοῦ πρηστῆρος καθιεμένου στρόβιλοι γίνονται, ὡς ἂν καὶ ἡ ἀπογέννησις κατὰ τὴν κίνησιν τοῦ πνεύματος γίνηται· ἕως δὲ θαλάττης δῖνοι ἀποτελοῦνται.", "st": "10.105"}, {"sp": "N", "t": "Σεισμοὺς ἐνδέχεται γίνεσθαι καὶ κατὰ πνεύματος ἐν τῇ γῇ ἀπόληψιν καὶ παρὰ μικροὺς ὄγκους αὐτῆς παράθεσιν καὶ συνεχῆ κίνησιν, ὃ τὸν κραδασμὸν τῇ γῇ παρασκευάζει. καὶ τὸ πνεῦμα τοῦτο ἢ ἔξωθεν ἐμπεριλαμβάνει 〈ἢ〉 ἐκ τοῦ πίπτειν [εἰς] ἐδάφη εἰς ἀντροειδεῖς τόπους τῆς γῆς ἐκπνευματοῦντα τὸν πεπιλημένον ἀέρα. 〈καὶ〉 κατ’ αὐτὴν δὲ τὴν διάδοσιν τῆς κινήσεως ἐκ τῶν πτώσεων ἐδαφῶν πολλῶν καὶ πάλιν ἀνταπόδοσιν, ὅταν πυκνώμασι σφοδροτέροις τῆς γῆς ἀπαντήσῃ, ἐνδέχεται σεισμοὺς ἀποτελεῖσθαι. καὶ κατ’ ἄλλους δὲ πλείους τρόπους τὰς κινήσεις ταύτας τῆς γῆς γίνεσθαι.", "st": "10.106"}, {"sp": "N", "t": "(τὰ δὲ πνεύματα συμβαίνει γίνεσθαι κατὰ χρόνον ἀλλοφυλίας τινὸς ἀεὶ καὶ κατὰ μικρὸν παρεισδυομένης, καὶ καθ’ ὕδατος ἀφθόνου συλλογήν·", "st": "10.106b"}, {"sp": "N", "t": "[τὰ δὲ λοιπὰ πνεύματα γίνεται] καὶ ὀλίγων πεσόντων εἰς τὰ πολλὰ κοιλώματα, διαδόσεως τούτων γινομένης.) Χάλαζα συντελεῖται καὶ κατὰ πῆξιν ἰσχυροτέραν, πάντοθεν δὲ πνευματωδῶν περίστασιν τινῶν καὶ καταμέρισιν· καὶ 〈κατὰ〉 πῆξιν μετριωτέραν, ὑδατοειδῶν 〈δέ〉 τινων ὁμούρησιν ἅμα τήν τε σύνωσιν αὐτῶν ποιουμένην καὶ τὴν διάρρηξιν πρὸς τὸ κατὰ μέρη συνίστασθαι πηγνύμενα καὶ κατὰ ἀθρότητα. ἡ δὲ περιφέρεια οὐκ ἀδυνάτως μὲν ἔχει γίνεσθαι πάντοθεν τῶν ἄκρων ἀποτηκομένων καὶ ἐν τῇ συστάσει πάντοθεν, ὡς λέγεται, κατὰ μέρη ὁμαλῶς περισταμένων εἴτε ὑδατοειδῶν τινων εἴτε πνευματωδῶν.", "st": "10.107"}, {"sp": "N", "t": "Χιόνα δὲ ἐνδέχεται συντελεῖσθαι καὶ ὕδατος λεπτοῦ ἐκχεομένου ἐκ τῶν νεφῶν (διὰ πόρων συμμετρίας καὶ θλίψεως ἐπιτηδείων νεφῶν καὶ ὑπὸ πνεύματος σπορᾶς), εἶτα τούτου πῆξιν ἐν τῇ φορᾷ λαμβάνοντος διά τινα ἰσχυρὰν ἐν τοῖς κατώτερον τόποις τῶν νεφῶν ψυχρασίας περίστασιν· καὶ κατὰ πῆξιν δ’ ἐν τοῖς νέφεσιν ὁμαλῆ ἀραιότητα ἔχουσαν τοιαύτη πρόεσις ἐκ τῶν νεφῶν γίνοιτο ἂν πρὸς ἄλληλα θλιβομένων, ὑδατοειδῶν τινων συμπαρακειμένων (ἃ οἱονεὶ σύνωσιν ποιούμενα χάλαζαν ἀποτελεῖ, ὃ μάλιστα γίνεται ἐν τῷ ἀέρι)· καὶ κατὰ τρῖψιν δὲ νεφῶν πῆξιν εἰληφότων ἀπόπαλσιν ἂν λαμβάνοι τὸ τῆς χιόνος τοῦτο ἄθροισμα. καὶ κατ’ ἄλλους δὲ τρόπους ἐνδέχεται χιόνα συντελεῖσθαι.", "st": "10.108"}, {"sp": "N", "t": "Δρόσος συντελεῖται καὶ κατὰ σύνοδον πρὸς ἄλληλα ἐκ τοῦ ἀέρος τῶν τοιούτων, ἃ τῆς τοιαύτης ὑγρασίας ἀποτελεστικὰ γίνεται· καὶ κατὰ 〈ἀπο〉φορὰν δὲ ἢ ἀπὸ νοτερῶν τόπων ἢ ὕδατα κεκτημένων (ἐν οἷς τόποις μάλιστα δρόσος συντελεῖται), εἶτα σύνοδον τούτων εἰς τὸ αὐτὸ λαβόντων καὶ ἀποτέλεσιν ὑγρασίας καὶ πάλιν φορὰν ἐπὶ τοὺς κάτω τόπους, καθάπερ ὁμοίως καὶ παρ’ ἡμῖν ἐπὶ πλειόνων τοιαῦτά τινα συντελούμενα θεωρεῖται.", "st": "10.108b"}, {"sp": "N", "t": "Καὶ πάχνη δὲ οὐ διαφερόντως συντελεῖται τῶν δρόσων τούτων πῆξίν τινα ποιὰν λαβόντων διὰ περίστασίν τινα ἀέρος ψυχροῦ.", "st": "10.109"}, {"sp": "N", "t": "Κρύσταλλος συντελεῖται καὶ κατ’ ἔκθλιψιν μὲν τοῦ περιφεροῦς σχηματισμοῦ ἐκ τοῦ ὕδατος, σύνωσιν δὲ τῶν σκαληνῶν καὶ ὀξυγωνίων τῶν ἐν τῷ ὕδατι ὑπαρχόντων· καὶ κατὰ ἔξωθεν δὲ τῶν τοιούτων πρόσκρισιν, ἃ συνελασθέντα πῆξιν τῷ ὕδατι παρεσκεύασε, ποσὰ τῶν περιφερῶν ἐκθλίψαντα.", "st": "10.109b"}, {"sp": "N", "t": "Ἶρις γίνεται κατὰ πρόσλαμψιν [ὑπὸ] τοῦ ἡλίου πρὸς ἀέρα ὑδατοειδῆ· ἢ κατὰ [ἀέρος] φύσιν ἰδίαν τοῦ τε φωτὸς καὶ τοῦ ἀέρος, ἣ τὰ τῶν χρωμάτων τούτων ἰδιώματα ποιήσει εἴτε πάντα εἴτε μονοειδῶς, ἀφ’ οὗ πάλιν ἀπολάμποντος τὰ ὁμοροῦντα τοῦ ἀέρος χρῶσιν ταύτην λήψεται, οἵαν θεωροῦμεν.... κατὰ πρόσλαμψιν πρὸς τὰ μέρη. Τὸ δὲ τῆς περιφερείας τούτου φάντασμα γίνεται διὰ τὸ τὸ διάστημα πάντοθεν ἴσον ὑπὸ τῆς ὄψεως θεωρεῖσθαι, ἢ σύνωσιν τοιαύτην λαμβανουσῶν τῶν ἐν τῷ ἀέρι 〈ἀ〉τόμων ἢ ἐν τοῖς νέφεσιν ἀπὸ τοῦ αὐτοῦ ἀέρος [προσφερομένου πρὸς τὴν σελήνην] ἀποφερομένων [ἀτόμων] περιφέρειάν τινα καθίεσθαι τὴν σύγκρισιν ταύτην.", "st": "10.110"}, {"sp": "N", "t": "Ἅλως περὶ τὴν σελήνην γίνεται [καὶ κατὰ] πάντοθεν ἀέρος προσφερομένου πρὸς τὴν σελήνην ἢ τὰ ἀπ’ αὐτῆς ῥεύματα ἀποφερόμενα ὁμαλῶς ἀναστέλλοντος ἐπὶ τοσοῦτον ἐφ’ ὅσον κύκλῳ περιστῆσαι τὸ νεφοειδὲς τοῦτο καὶ μὴ τὸ παράπαν διακρῖναι, ἢ καὶ τὸν πέριξ αὐτῆς ἀέρα ἀναστέλλοντος συμμέτρως πάντοθεν εἰς τὸ περιφερὲς τὸ περὶ αὐτὴν καὶ παχυμερὲς περιστῆσαι. ὃ γίνεται κατὰ μέρη τινὰ ἤτοι ἔξωθεν βιασαμένου τινὸς ῥεύματος ἢ τῆς θερμασίας ἐπιτηδείων πόρων ἐπιλαμβανομένης εἰς τὸ τοῦτο ἀπεργάσασθαι.", "st": "10.111"}, {"sp": "N", "t": "Κομῆται ἀστέρες γίνονται ἤτοι πυρὸς ἐν τόποις τισὶ διὰ χρόνων τινῶν ἐν τοῖς μετεώροις συντρεφομένου περιστάσεως γινομένης, ἢ ἰδίαν τινὰ κίνησιν διὰ χρόνων τοῦ οὐρανοῦ ἴσχοντος ὑπὲρ ἡμᾶς, ὥστε τὰ τοιαῦτα ἄστρα ἀναφανῆναι (ἢ αὐτὰ ἐν χρόνοις τισὶν ὁρμῆσαι διά τινα περίστασιν καὶ εἰς τοὺς καθ’ ἡμᾶς τόπους ἐλθεῖν καὶ ἐκφανῆ γενέσθαι. τήν τε ἀφάνισιν τούτων γίνεσθαι παρὰ τὰς ἀντικειμένας ταύταις αἰτίας).", "st": "10.111b"}, {"sp": "N", "t": "〈Τῶν ἄστρων〉 τινὰ ἀναστρέφεται αὐτοῦ, ὃ συμβαίνει οὐ μόνον τῷ τὸ μέρος τοῦτο τοῦ κόσμου ἑστάναι, περὶ ὃ τὸ λοιπὸν στρέφεται, καθάπερ τινές φασιν, ἀλλὰ καὶ τῷ δίνην ἀέρος ἔγκυκλον αὐτοῖς περιεστάναι, ἢ κωλυτικὴ γίνεται τοῦ περιπολεῖν ὡς καὶ τὰ ἄλλα· ἢ καὶ διὰ τὸ ἑξῆς μὲν αὐτοῖς ὕλην ἐπιτηδείαν μὴ εἶναι, ἐν δὲ τούτῳ τῷ τόπῳ ἐν ᾧ κείμενα θεωρεῖται. καὶ κατ’ ἄλλους δὲ πλείονας τρόπους τοῦτο δυνατὸν συντελεῖσθαι, ἐάν τις δύνηται τὸ σύμφωνον τοῖς φαινομένοις συλλογίζεσθαι. Τινὰ τῶν ἄστρων πλανᾶσθαι, εἰ οὕτω ταῖς κινήσεσι χρώμενα συμβαίνει, τινὰ δὲ μὴ [κινεῖσθαι] ἐνδέχεται μὲν καὶ παρὰ τὸ κύκλῳ κινούμενα ἐξ ἀρχῆς οὕτω κατηναγκάσθαι, ὥστε τὰ μὲν κατὰ τὴν αὐτὴν δῖναν φέρεσθαι ὁμαλὴν οὖσαν, τὰ δὲ κατὰ τὴν ἅμα τισὶν ἀνωμαλίαις χρωμένην· ἐνδέχεται δὲ καὶ καθ’ οὓς τόπους φέρεται οὗ μὲν παρεκτάσεις ἀέρος εἶναι ὁμαλεῖς ἐπὶ τὸ αὐτὸ συνωθούσας κατὰ τὸ ἑξῆς ὁμαλῶς τε ἐκκαούσας, οὗ δὲ ἀνωμαλεῖς οὕτως ὥστε τὰς θεωρουμένας παραλλαγὰς συντελεῖσθαι. τὸ δὲ μίαν αἰτίαν τούτων ἀποδιδόναι, πλεοναχῶς τῶν φαινομένων ἐκκαλουμένων, μανικὸν καὶ οὐ καθηκόντως πραττόμενον ὑπὸ τῶν τὴν ματαίαν ἀστρολογίαν ἐζηλωκότων καὶ εἰς τὸ κενὸν αἰτίας τινῶν ἀποδιδόντων, ὅταν τὴν θείαν φύσιν μηθαμῇ λειτουργιῶν ἀπολύωσι.", "st": "10.112"}, {"sp": "N", "t": "Τινὰ ἄστρα ὑπολειπόμενά τινων θεωρεῖσθαι συμβαίνει καὶ παρὰ τὸ βραδύτερον συμπεριφέρεσθαι τὸν αὐτὸν κύκλον περιόντα, καὶ παρὰ τὸ τὴν ἐναντίαν κινεῖσθαι ἀντισπώμενα ὑπὸ τῆς αὐτῆς δίνης, καὶ παρὰ τὸ περιφέρεσθαι τὰ μὲν διὰ πλείονος τόπου, τὰ δὲ δι’ ἐλάττονος, τὴν αὐτὴν δῖναν περικυκλοῦντα. τὸ δὲ ἁπλῶς ἀποφαίνεσθαι περὶ τούτων καθῆκόν ἐστι τοῖς τερατεύεσθαί τι πρὸς τοὺς πολλοὺς βουλομένοις.", "st": "10.114"}, {"sp": "N", "t": "Οἱ λεγόμενοι ἀστέρες ἐκπίπτειν (καὶ) παρὰ μέρος (καὶ παρὰ τρῖψιν† ἑαυτῶν) δύνανται συντελεῖσθαι (καὶ παρὰ ἔκπτωσιν οὗ ἂν ἡ ἐκπνευμάτωσις γένηται), καθάπερ καὶ ἐπὶ τῶν ἀστραπῶν ἐλέγομεν· καὶ κατὰ σύνοδον δὲ ἀτόμων πυρὸς ἀποτελεστικῶν, συμφυλίας γενομένης εἰς τὸ τοῦτο τελέσαι, καὶ κατὰ κίνησιν οὗ ἂν ἡ ὁρμὴ ἐξ ἀρχῆς κατὰ τὴν σύνοδον γένηται· καὶ κατὰ πνευμάτων δὲ συλλογὴν ἐν πυκνώμασί τισιν [ἐν] ὀμιχλοειδέσι καὶ ἐκπύρωσιν τούτων διὰ τὴν κατείλησιν, εἶτ’ [ἐπ]ἔκρηξιν 〈ἐκ〉 τῶν περιεχόντων, καὶ ἐφ’ ὃν ἂν τόπον ἡ ὁρμὴ γένηται τῆς φορᾶς, εἰς τοῦτον φερομένων. καὶ ἄλλοι δὲ τρόποι εἰς τοῦτο τελέσαι ἀμύθητοί εἰσιν.", "st": "10.115"}, {"sp": "N", "t": "Αἱ δ’ ἐπισημασίαι αἱ γινόμεναι ἐπί τισι ζῴοις κατὰ συγκύρημα γίνονται τοῦ καιροῦ. οὐ γὰρ τὰ ζῷα ἀνάγκην τινὰ προσφέρεται τοῦ ἀποτελεσθῆναι χειμῶνα, οὐδὲ κάθηταί τις θεία φύσις παρατηροῦσα τὰς τῶν ζῴων τούτων ἐξόδους κἄπειτα τὰς ἐπισημασίας ταύτας ἐπιτελεῖ. οὐδὲ γὰρ 〈ἂν〉 εἰς τὸ τυχὸν ζῷον κἂν μικρῷ χαριέστερον ᾖ, ἡ τοιαύτη μωρία ἐκπέσοι, μὴ ὅτι εἰς παντελῆ εὐδαιμονίαν κεκτημένον.", "st": "10.116"}, {"sp": "N", "t": "Ταῦτα δὴ πάντα, Πυθόκλεις, μνημόνευσον· κατὰ πολύ τε γὰρ τοῦ μύθου ἐκβήσῃ καὶ τὰ ὁμογενῆ τούτοις συνορᾶν δυνήσῃ, μάλιστα δὲ σεαυτὸν ἀπόδος εἰς τὴν τῶν ἀρχῶν καὶ ἀπειρίας καὶ τῶν συγγενῶν τούτοις θεωρίαν, ἔτι τε κριτηρίων καὶ παθῶν, καὶ οὗ ἕνεκεν ταῦτα ἐκλογιζόμεθα. ταῦτα γὰρ μάλιστα συνθεωρούμενα ῥᾳδίως τὰς περὶ τῶν κατὰ μέρος αἰτίας συνορᾶν ποιήσει. οἱ δὲ ταῦτα μὴ καταγαπήσαντες ᾖ μάλιστα οὔτε 〈ἂν〉 αὐτὰ ταῦτα καλῶς συνθεωρήσαιεν οὔτε οὗ ἕνεκεν δεῖ θεωρεῖν ταῦτα περιεποιήσαντο.", "st": "10.116b"}, {"sp": "HDR", "t": "Ἐπίκουρος Μενοικεῖ χαίρειν"}, {"sp": "N", "t": "Μήτε νέος τις ὢν μελλέτω φιλοσοφεῖν, μήτε γέρων ὑπάρχων κοπιάτω φιλοσοφῶν. οὔτε γὰρ ἄωρος οὐδείς ἐστιν οὔτε πάρωρος πρὸς τὸ κατὰ ψυχὴν ὑγιαῖνον. ὁ δὲ λέγων ἢ μήπω τοῦ φιλοσοφεῖν ὑπάρχειν ὥραν ἢ παρεληλυθέναι τὴν ὥραν ὅμοιός ἐστι τῷ λέγοντι πρὸς εὐδαιμονίαν ἢ μὴ παρεῖναι τὴν ὥραν ἢ μηκέτι εἶναι. ὥστε φιλοσοφητέον καὶ νέῳ καὶ γέροντι, τῷ μὲν ὅπως γηράσκων νεάζῃ τοῖς ἀγαθοῖς διὰ τὴν χάριν τῶν γεγονότων, τῷ δὲ ὅπως νέος ἅμα καὶ παλαιὸς ᾖ διὰ τὴν ἀφοβίαν τῶν μελλόντων·", "st": "10.122"}, {"sp": "N", "t": "μελετᾶν οὖν χρὴ τὰ ποιοῦντα τὴν εὐδαιμονίαν, εἴπερ παρούσης μὲν αὐτῆς πάντα ἔχομεν, ἀπούσης δὲ πάντα πράττομεν εἰς τὸ ταύτην ἔχειν. Ἃ δέ σοι συνεχῶς παρήγγελλον, ταῦτα καὶ πρᾶττε καὶ μελέτα, στοιχεῖα τοῦ καλῶς ζῆν ταῦτ’ εἶναι διαλαμβάνων. Πρῶτον μὲν τὸν θεὸν ζῷον ἄφθαρτον καὶ μακάριον νομίζων, ὡς ἡ κοινὴ τοῦ θεοῦ νόησις ὑπεγράφη, μηθὲν μήτε τῆς ἀφθαρσίας ἀλλότριον μήτε τῆς μακαριότητος ἀνοίκειον αὐτῷ πρόσαπτε· πᾶν δὲ τὸ φυλάττειν αὐτοῦ δυνάμενον τὴν μετὰ ἀφθαρσίας μακαριότητα περὶ αὐτὸν δόξαζε. θεοὶ μὲν γὰρ εἰσίν· ἐναργὴς γὰρ αὐτῶν ἐστιν ἡ γνῶσις· οἵους δ’ αὐτοὺς 〈οἱ〉 πολλοὶ νομίζουσιν, οὐκ εἰσίν· οὐ γὰρ φυλάττουσιν αὐτοὺς οἵους νομίζουσιν. ἀσεβὴς δὲ οὐχ ὁ τοὺς τῶν πολλῶν θεοὺς ἀναιρῶν, ἀλλ’ ὁ τὰς τῶν πολλῶν δόξας θεοῖς προσάπτων. οὐ γὰρ προλήψεις εἰσὶν ἀλλ’ ὑπολήψεις ψευδεῖς αἱ τῶν πολλῶν ὑπὲρ θεῶν ἀποφάσεις. ἔνθεν αἱ μέγισται βλάβαι† αἴτιαι τοῖς κακοῖς ἐκ θεῶν ἐπάγονται καὶ ὠφέλειαι. ταῖς γὰρ ἰδίαις οἰκειούμενοι διὰ παντὸς ἀρεταῖς τοὺς ὁμοίους ἀποδέχονται, πᾶν τὸ μὴ τοιοῦτον ὡς ἀλλότριον νομίζοντες.", "st": "10.123"}, {"sp": "N", "t": "Συνέθιζε δὲ ἐν τῷ νομίζειν μηδὲν πρὸς ἡμᾶς εἶναι τὸν θάνατον· ἐπεὶ πᾶν ἀγαθὸν καὶ κακὸν ἐν αἰσθήσει· στέρησις δέ ἐστιν αἰσθήσεως ὁ θάνατος. ὅθεν γνῶσις ὀρθὴ τοῦ μηθὲν εἶναι πρὸς ἡμᾶς τὸν θάνατον ἀπολαυστὸν ποιεῖ τὸ τῆς ζωῆς θνητόν, οὐκ ἄπειρον προστιθεῖσα χρόνον, ἀλλὰ τὸν τῆς ἀθανασίας ἀφελομένη πόθον. οὐθὲν γάρ ἐστιν ἐν τᾷ ζῆν δεινὸν τῷ κατειληφότι γνησίως τὸ μηδὲν ὑπάρχειν ἐν τῷ μὴ ζῆν δεινόν. ὥστε μάταιος ὁ λέγων δεδιέναι τὸν θάνατον οὐχ ὅτι λυπήσει παρών, ἀλλ’ ὅτι λυπεῖ μέλλων. ὃ γὰρ παρὸν οὐκ ἐνοχλεῖ, προσδοκώμενον κενῶς λυπεῖ. τὸ φρικωδέστατον οὖν τῶν κακῶν ὁ θάνατος οὐθὲν πρὸς ἡμᾶς, ἐπειδήπερ ὅταν μὲν ἡμεῖς ὦμεν, ὁ θάνατος οὐ πάρεστιν, ὅταν δὲ ὁ θάνατος παρῇ, τόθ’ ἡμεῖς οὐκ ἐσμέν. οὔτε οὖν πρὸς τοὺς ζῶντάς ἐστιν οὔτε πρὸς τοὺς τετελευτηκότας, ἐπειδήπερ περὶ οὓς μὲν οὐκ ἔστιν, οἳ δ’ οὐκέτι εἰσίν. Ἀλλ’ οἱ πολλοὶ τὸν θάνατον ὁτὲ μὲν ὡς μέγιστον τῶν κακῶν φεύγουσιν, ὁτὲ δὲ ὡς ἀνάπαυσιν τῶν ἐν τῷ ζῆν 〈κακῶν αἱροῦνται. ὁ δὲ σοφὸς οὔτε παραιτεῖται τὸ ζῆν〉 οὔτε φοβεῖται τὸ μὴ ζῆν· οὔτε γὰρ αὐτῷ προσίσταται τὸ ζῆν οὔτε δοξάζει κακὸν εἶναί τι τὸ μὴ ζῆν. ὥσπερ δὲ τὸ σιτίον οὐ τὸ πλεῖον πάντως ἀλλὰ τὸ ἥδιστον αἱρεῖται, οὕτω καὶ χρόνον οὐ τὸν μήκιστον ἀλλὰ τὸν ἥδιστον καρπίζεται. Ὁ δὲ παραγγέλλων τὸν μὲν νέον καλῶς ζῆν, τὸν δὲ γέροντα καλῶς καταστρέφειν, εὐήθης ἐστὶν οὐ μόνον διὰ τὸ τῆς ζωῆς ἀσπαστόν, ἀλλὰ καὶ διὰ τὸ τὴν αὐτὴν εἶναι μελέτην τοῦ καλῶς ζῆν καὶ τοῦ καλῶς ἀποθνήσκειν. πολὺ δὲ χείρων καὶ ὁ λέγων καλὸν μὲν μὴ φῦναι, φύντα δ’ ὅπως ὤκιστα πύλας Ἀίδαο περῆσαι.", "st": "10.125"}, {"sp": "N", "t": "Εἰ μὲν γὰρ πεποιθὼς τοῦτό φησιν, πῶς οὐκ ἀπέρχεται ἐκ τοῦ ζῆν; ἐν ἑτοίμῳ γὰρ αὐτῷ τοῦτ’ ἐστίν, εἴπερ ἦν βεβουλευμένον αὐτῷ βεβαίως· εἰ δὲ μωκώμενος, μάταιος ἐν τοῖς οὐκ ἐπιδεχομένοις. Μνημονευτέον δὲ ὡς τὸ μέλλον 〈οὔτε πάντως ἡμέτερον〉 οὔτε πάντως οὐχ ἡμέτερον, ἵνα μήτε πάντως προσμένωμεν ὡς ἐσόμενον μήτε ἀπελπίζωμεν ὡς πάντως οὐκ ἐσόμενον. Ἀναλογιστέον δὲ ὡς τῶν ἐπιθυμιῶν αἱ μέν εἰσι φυσικαί, αἱ δὲ κεναί, καὶ τῶν φυσικῶν αἱ μὲν ἀναγκαῖαι, αἱ δὲ φυσικαὶ μόνον· τῶν δὲ ἀναγκαίων αἱ μὲν πρὸς εὐδαιμονίαν εἰσὶν ἀναγκαῖαι, αἱ δὲ πρὸς τὴν τοῦ σώματος ἀοχλησίαν, αἱ δὲ πρὸς αὐτὸ τὸ ζῆν. τούτων γὰρ ἀπλανὴς θεωρία πᾶσαν αἵρεσιν καὶ φυγὴν ἐπανάγειν οἶδεν ἐπὶ τὴν τοῦ σώματος ὑγίειαν καὶ τὴν 〈τῆς ψυχῆς〉 ἀταραξίαν, ἐπεὶ τοῦτο τοῦ μακαρίως ζῆν ἐστι τέλος. τούτου γὰρ χάριν πάντα πράττομεν, ὅπως μήτε ἀλγῶμεν μήτε ταρβῶμεν. ὅταν δὲ ἅπαξ τοῦτο περὶ ἡμᾶς γένηται, λύεται πᾶς ὁ τῆς ψυχῆς χειμών, οὐκ ἔχοντος τοῦ ζῴου βαδίζειν ὡς πρὸς ἐνδέον τι καὶ ζητεῖν ἕτερον ᾧ τὸ τῆς ψυχῆς καὶ τοῦ σώματος ἀγαθὸν συμπληρώσεται.", "st": "10.127"}, {"sp": "N", "t": "τότε γὰρ ἡδονῆς χρείαν ἔχομεν, ὅταν ἐκ τοῦ μὴ παρεῖναι τὴν ἡδονὴν ἀλγῶμεν· 〈ὅταν δὲ μὴ ἀλγῶμεν〉, οὐκέτι τῆς ἡδονῆς δεόμεθα. Καὶ διὰ τοῦτο τὴν ἡδονὴν ἀρχὴν καὶ τέλος λέγομεν εἶναι τοῦ μακαρίως ζῆν. ταύτην γὰρ ἀγαθὸν πρῶτον καὶ συγγενικὸν ἔγνωμεν, καὶ ἀπὸ ταύτης καταρχόμεθα πάσης αἱρέσεως καὶ φυγῆς, καὶ ἐπὶ ταύτην καταντῶμεν ὡς κανόνι τῷ πάθει πᾶν ἀγαθὸν κρίνοντες. Καὶ ἐπεὶ πρῶτον ἀγαθὸν τοῦτο καὶ σύμφυτον, διὰ τοῦτο καὶ οὐ πᾶσαν ἡδονὴν αἱρούμεθα, ἀλλ’ ἔστιν ὅτε πολλὰς ἡδονὰς ὑπερβαίνομεν, ὅταν πλεῖον ἡμῖν τὸ δυσχερὲς ἐκ τούτων ἕπηται· καὶ πολλὰς ἀλγηδόνας ἡδονῶν κρείττους νομίζομεν, ἐπειδὰν μείζων ἡμῖν ἡδονὴ παρακολουθῇ πολὺν χρόνον ὑπομείνασι τὰς ἀλγηδόνας.", "st": "10.129"}, {"sp": "N", "t": "πᾶσα οὖν ἡδονὴ διὰ τὸ φύσιν ἔχειν οἰκείαν ἀγαθόν, οὐ πᾶσα μέντοι αἱρετή· καθάπερ καὶ ἀλγηδὼν πᾶσα κακόν, οὐ πᾶσα δὲ ἀεὶ φευκτὴ πεφυκυῖα. τῇ μέντοι συμμετρήσει καὶ συμφερόντων καὶ ἀσυμφόρων βλέψει ταῦτα πάντα κρίνειν καθήκει. χρώμεθα γὰρ τῷ μὲν ἀγαθῷ κατά τινας χρόνους ὡς κακῷ, τῷ δὲ κακῷ τοὔμπαλιν ὡς ἀγαθῷ. Καὶ τὴν αὐτάρκειαν δὲ ἀγαθὸν μέγα νομίζομεν, οὐχ ἵνα πάντως τοῖς ὀλίγοις χρώμεθα, ἀλλ’ ὅπως ἐὰν μὴ ἔχωμεν τὰ πολλά, τοῖς ὀλίγοις ἀρκώμεθα, πεπεισμένοι γνησίως ὅτι ἥδιστα πολυτελείας ἀπολαύουσιν οἱ ἥκιστα ταύτης δεόμενοι, καὶ ὅτι τὸ μὲν φυσικὸν πᾶν εὐπόριστόν ἐστι, τὸ δὲ κενὸν δυσπόριστον, ὅτι τε λιτοὶ χυλοὶ ἴσην πολυτελεῖ διαίτῃ τὴν ἡδονὴν ἐπιφέρουσιν, ὅταν ἅπαν τὸ ἀλγοῦν κατ’ ἔνδειαν ἐξαιρεθῇ, καὶ μᾶζα καὶ ὕδωρ τὴν ἀκροτάτην ἀποδίδωσιν ἡδονήν, ἐπειδὰν ἐνδέων τις αὐτὰ προσενέγκηται. τὸ συνεθίζειν οὖν ἐν ταῖς ἁπλαῖς καὶ οὐ πολυτελέσι διαίταις καὶ ὑγιείας ἐστὶ συμπληρωτικὸν καὶ πρὸς τὰς ἀναγκαίας τοῦ βίου χρήσεις ἄοκνον ποιεῖ τὸν ἄνθρωπον καὶ τοῖς πολυτελέσιν ἐκ διαλειμμάτων προσερχομένοις κρεῖττον ἡμᾶς διατίθησι καὶ πρὸς τὴν τύχην ἀφόβους παρασκευάζει. Ὅταν οὖν λέγωμεν ἡδονὴν τέλος ὑπάρχειν, οὐ τὰς τῶν ἀσώτων ἡδονὰς καὶ τὰς ἐν ἀπολαύσει κειμένας λέγομεν, ὥς τινες ἀγνοοῦντες καὶ οὐχ ὁμολογοῦντες ἢ κακῶς ἐκδεχόμενοι νομίζουσιν, ἀλλὰ τὸ μήτε ἀλγεῖν κατὰ σῶμα μήτε ταράττεσθαι κατὰ ψυχήν· οὐ γὰρ πότοι καὶ κῶμοι συνείροντες οὐδ’ ἀπολαύσεις παίδων καὶ γυναικῶν οὐδ’ ἰχθύων καὶ τῶν ἄλλων, ὅσα φέρει πολυτελὴς τράπεζα, τὸν ἡδὺν γεννᾷ βίον, ἀλλὰ νήφων λογισμὸς καὶ τὰς αἰτίας ἐξερευνῶν πάσης αἱρέσεως καὶ φυγῆς καὶ τὰς δόξας ἐξελαύνων, ἐξ ὧν πλεῖστος τὰς ψυχὰς καταλαμβάνει θόρυβος.", "st": "10.130"}, {"sp": "N", "t": "Τούτων δὲ πάντων ἀρχὴ καὶ τὸ μέγιστον ἀγαθὸν φρόνησις. διὸ καὶ φιλοσοφίας τιμιώτερον ὑπάρχει φρόνησις, ἐξ ἧς αἱ λοιπαὶ πᾶσαι πεφύκασιν ἀρεταί, διδάσκουσα ὡς οὐκ ἔστιν ἡδέως ζῆν ἄνευ τοῦ φρονίμως καὶ καλῶς καὶ δικαίως 〈οὐδὲ φρονίμως καὶ καλῶς καὶ δικαίως〉 ἄνευ τοῦ ἡδέως. συμπεφύκασι γὰρ αἱ ἀρεταὶ τῷ ζῆν ἡδέως, καὶ τὸ ζῆν ἡδέως τούτων ἐστὶν ἀχώριστον. Ἐπεὶ τίνα νομίζεις εἶναι κρείττονα τοῦ καὶ περὶ θεῶν ὅσια δοξάζοντος καὶ περὶ θανάτου διὰ παντὸς ἀφόβως ἔχοντος καὶ τὸ τῆς φύσεως ἐπιλελογισμένου τέλος, καὶ τὸ μὲν τῶν ἀγαθῶν πέρας ὡς ἔστιν εὐσυμπλήρωτόν τε καὶ εὐπόριστον διαλαμβάνοντος, τὸ δὲ τῶν κακῶν ὡς ἢ χρόνους ἢ πόνους ἔχει βραχεῖς; τὴν δὲ ὑπό τινων δεσπότιν εἰσαγομένην πάντων †ἀγγέλλοντος * * (〈λέγει ἐν ἄλλοις γίνεσθαι ἃ μὲν κατ’ ἀνάγκην〉, ἃ δὲ ἀπὸ τύχης, ἃ δὲ παρ’ ἡμᾶς, διὰ τὸ τὴν μὲν ἀνάγκην ἀνυπεύθυνον εἶναι, τὴν δὲ τύχην ἄστατον ὁρᾶν, τὸ δὲ παρ’ ἡμᾶς ἀδέσποτον, ᾧ καὶ τὸ μεμπτὸν καὶ τὸ ἐναντίον παρακολουθεῖν πέφυκεν) — ἐπεὶ κρεῖττον ἦν τῷ περὶ θεῶν μύθῳ κατακολουθεῖν ἢ τῇ τῶν φυσικῶν εἱμαρμένῃ δουλεύειν·", "st": "10.133"}, {"sp": "N", "t": "ὁ μὲν γὰρ ἐλπίδα παραιτήσεως ὑπογράφει θεῶν διὰ τιμῆς, ἣ δὲ ἀπαραίτητον ἔχει τὴν ἀνάγκην — τὴν δὲ τύχην οὔτε θεὸν ὡς οἱ πολλοὶ νομίζουσιν ὑπολαμβάνων — οὐθὲν γὰρ ἀτάκτως θεῷ πράττεται ἀβέβαιον οὔτε αἰτίαν — 〈οὐκ〉 οἴεται μὲν γὰρ ἀγαθὸν ἢ κακὸν ἐκ ταύτης πρὸς τὸ μακαρίως ζῆν ἀνθρώποις δίδοσθαι, ἀρχὰς μέντοι μεγάλων ἀγαθῶν ἢ κακῶν ὑπὸ ταύτης χορηγεῖσθαι — κρεῖττον εἶναι νομίζων εὐλογίστως ἀτυχεῖν ἢ ἀλογίστως εὐτυχεῖν — βέλτιον γὰρ ἐν ταῖς πράξεσι τὸ καλῶς κριθὲν 〈μὴ ὀρθωθῆναι ἢ τὸ μὴ καλῶς κριθὲν〉 ὀρθωθῆναι διὰ ταύτην.", "st": "10.135"}, {"sp": "N", "t": "Ταῦτα οὖν καὶ τὰ τούτοις συγγενῆ μελέτα πρὸς σεαυτὸν ἡμέρας καὶ νυκτὸς πρός 〈τε〉 τὸν ὅμοιον σεαυτῷ, καὶ οὐδέποτε οὔθ’ ὕπαρ οὔτ’ ὄναρ διαταραχθήσῃ, ζήσῃ δὲ ὡς θεὸς ἐν ἀνθρώποις. οὐθὲν γὰρ ἔοικε θνητῷ ζῴῳ ζῶν ἄνθρωπος ἐν ἀθανάτοις ἀγαθοῖς.", "st": "10.135b"}, {"sp": "HDR", "t": "ΚΥΡΙΑΙ ΔΟΞΑΙ"}, {"sp": "N", "t": "Τὸ μακάριον καὶ ἄφθαρτον οὔτε αὐτὸ πράγματα ἔχει οὔτε ἄλλῳ παρέχει, ὥστε οὔτε ὀργαῖς οὔτε χάρισι συνέχεται· ἐν ἀσθενεῖ γὰρ πᾶν τὸ τοιοῦτον.", "st": "M1"}, {"sp": "N", "t": "(ἐν ἄλλοις δέ φησι τοὺς θεοὺς λόγῳ θεωρητούς, οὓς μὲν κατ’ ἀριθμὸν ὑφεστῶτας, οὓς δὲ κατὰ ὁμοείδειαν ἐκ τῆς συνεχοῦς ἐπιρρύσεως τῶν ὁμοίων εἰδώλων ἐπὶ τὸ αὐτὸ ἀποτετελεσμένων, ἀνθρωποειδεῖς.)", "st": "M1b"}, {"sp": "N", "t": "Ὁ θάνατος οὐδὲν πρὸς ἡμᾶς· τὸ γὰρ διαλυθὲν ἀναισθητεῖ· τὸ δ’ ἀναισθητοῦν οὐδὲν πρὸς ἡμᾶς.", "st": "M2"}, {"sp": "N", "t": "Ὅρος τοῦ μεγέθους τῶν ἡδονῶν ἡ παντὸς τοῦ ἀλγοῦντος ὑπεξαίρεσις. ὅπου δ’ ἂν τὸ ἡδόμενον ἐνῇ, καθ’ ὃν ἂν χρόνον ᾖ, οὐκ ἔστι τὸ ἀλγοῦν ἢ λυπούμενον ἢ τὸ συναμφότερον.", "st": "M3"}, {"sp": "N", "t": "Οὐ χρονίζει τὸ ἀλγοῦν συνεχῶς ἐν τῇ σαρκί, ἀλλὰ τὸ μὲν ἄκρον τὸν ἐλάχιστον χρόνον πάρεστι, τὸ δὲ μόνον ὑπερτεῖνον τὸ ἡδόμενον κατὰ σάρκα οὐ πολλὰς ἡμέρας συμμένει. αἱ δὲ πολυχρόνιοι τῶν ἀρρωστιῶν πλεονάζον ἔχουσι τὸ ἡδόμενον ἐν τῇ σαρκὶ ἤπερ τὸ ἀλγοῦν.", "st": "M4"}, {"sp": "N", "t": "Οὐκ ἔστιν ἡδέως ζῆν ἄνευ τοῦ φρονίμως καὶ καλῶς καὶ δικαίως 〈οὐδὲ φρονίμως καὶ καλῶς καὶ δικαίως〉 ἄνευ τοῦ ἡδέως. ὅτῳ δὲ τοῦτο μὴ ὑπάρχει, [οὐ ζῇ φρονίμως. καὶ καλῶς καὶ δικαίως ὑπάρχει] οὐκ ἔστι τοῦτον ἡδέως ζῆν.", "st": "M5"}, {"sp": "N", "t": "Ἕνεκα τοῦ θαρρεῖν ἐξ ἀνθρώπων ἦν κατὰ φύσιν ἀρχῆς καὶ βασιλείας ἀγαθόν, ἐξ ὧν ἄν ποτε τοῦτο οἷός τ’ ᾖ παρασκευάζεσθαι. Ἔνδοξοι καὶ περίβλεπτοί τινες ἐβουλήθησαν γενέσθαι, τὴν ἐξ ἀνθρώπων ἀσφάλειαν οὕτω νομίζοντες περιποιήσεσθαι. ὥστε εἰ μὲν ἀσφαλὴς ὁ τῶν τοιούτων βίος, ἀπέλαβον τὸ τῆς φύσεως ἀγαθόν· εἰ δὲ μὴ ἀσφαλής, οὐκ ἔχουσιν οὗ ἕνεκα ἐξ ἀρχῆς κατὰ τὸ τῆς φύσεως οἰκεῖον ὠρέχθησαν.", "st": "M6"}, {"sp": "N", "t": "Οὐδεμία ἡδονὴ καθ’ ἑαυτὴν κακόν· ἀλλὰ τὰ τινῶν ἡδονῶν ποιητικὰ πολλαπλασίους ἐπιφέρει τὰς ὀχλήσεις τῶν ἡδονῶν.", "st": "M7"}, {"sp": "N", "t": "Εἰ κατεπυκνοῦτο πᾶσα ἡδονή, καὶ χρόνῳ καὶ περὶ ὅλον τὸ ἄθροισμα ὑπῆρχεν ἢ τὰ κυριώτατα μέρη τῆς φύσεως, οὐκ ἄν ποτε διέφερον ἀλλήλων αἱ ἡδοναί.", "st": "M8"}, {"sp": "N", "t": "Εἰ τὰ ποιητικὰ τῶν περὶ τοὺς ἀσώτους ἡδονῶν ἔλυε τοὺς φόβους τῆς διανοίας τούς τε περὶ μετεώρων καὶ θανάτου καὶ ἀλγηδόνων, ἔτι τε τὸ πέρας τῶν ἐπιθυμιῶν ἐδίδασκεν, οὐκ ἄν ποτε εἴχομεν ὅ τι μεμψαίμεθα αὐτοῖς, πανταχόθεν ἐκπληρουμένοις τῶν ἡδονῶν καὶ οὐθαμόθεν οὔτε τὸ ἀλγοῦν.", "st": "M9"}, {"sp": "N", "t": "Εἰ μηθὲν ἡμᾶς αἱ τῶν μετεώρων ὑποψίαι ἠνώχλουν καὶ αἱ περὶ θανάτου, μή ποτε πρὸς ἡμᾶς ᾖ τι, ἔτι τε τὸ μὴ κατανοεῖν τοὺς ὅρους τῶν ἀλγηδόνων καὶ τῶν ἐπιθυμιῶν, οὐκ ἂν προσεδεόμεθα φυσιολογίας.", "st": "M10"}, {"sp": "N", "t": "Οὐκ ἦν τὸ φοβούμενον λύειν ὑπὲρ τῶν κυριωτάτων μὴ κατειδότα τίς ἡ τοῦ σύμπαντος φύσις, ἀλλ’ ὑποπτεύοντά τι τῶν κατὰ τοὺς μύθους. ὥστε οὐκ ἦν ἄνευ φυσιολογίας ἀκεραίους τὰς ἡδονὰς ἀπολαμβάνειν.", "st": "M11"}, {"sp": "N", "t": "Οὐθὲν ὄφελος ἦν τὴν κατὰ ἀνθρώπους ἀσφάλειαν κατασκευάζεσθαι τῶν ἄνωθεν ὑπόπτων καθεστώτων καὶ τῶν ὑπὸ γῆς καὶ ἁπλῶς τῶν ἐν τῷ ἀπείρῳ.", "st": "M12"}, {"sp": "N", "t": "Τῆς ἀσφαλείας τῆς ἐξ ἀνθρώπων γενομένης μέχρι τινὸς δυνάμει τε ἐξερειστικῇ καὶ εὐπορίᾳ εἰλικρινεστέρα γίνεται ἡ ἐκ τῆς ἡσυχίας καὶ ἐκχωρήσεως τῶν πολλῶν ἀσφάλεια.", "st": "M13"}, {"sp": "N", "t": "Ὁ τῆς φύσεως πλοῦτος καὶ ὥρισται καὶ εὐπόριστός ἐστιν· ὁ δὲ τῶν κενῶν δοξῶν εἰς ἄπειρον ἐκπίπτει.", "st": "M14"}, {"sp": "N", "t": "Βραχέα σοφῷ τύχη παρεμπίπτει, τὰ δὲ μέγιστα καὶ κυριώτατα ὁ λογισμὸς διῴκηκε καὶ κατὰ τὸν συνεχῆ χρόνον τοῦ βίου διοικεῖ καὶ διοικήσει.", "st": "M15"}, {"sp": "N", "t": "Ὁ δίκαιος 〈βίος〉 ἀταρακτότατος, ὁ δ’ ἄδικος πλείστης ταραχῆς γέμων.", "st": "M16"}, {"sp": "N", "t": "Οὐκ ἐπαύξεται ἐν τῇ σαρκὶ ἡ ἡδονή, ἐπειδὰν ἅπαξ τὸ κατ’ ἔνδειαν ἀλγοῦν ἐξαιρεθῇ, ἀλλὰ μόνον ποικίλλεται·", "st": "M17"}, {"sp": "N", "t": "τῆς δὲ διανοίας τὸ πέρας τὸ κατὰ τὴν ἡδονὴν ἀπεγέννησεν ἥ τε τούτων αὐτῶν ἐκλόγισις καὶ τῶν ὁμογενῶν τούτοις, ὅσα τοὺς μεγίστους φόβους παρεσκεύαζε τῇ διανοίᾳ.", "st": "M18"}, {"sp": "N", "t": "Ὁ ἄπειρος χρόνος ἴσην ἔχει τὴν ἡδονὴν καὶ ὁ πεπερασμένος, ἐάν τις αὐτῆς τὰ πέρατα καταμετρήσῃ τῷ λογισμῷ.", "st": "M19"}, {"sp": "N", "t": "Ἡ μὲν σὰρξ ἀπέλαβε τὰ πέρατα τῆς ἡδονῆς ἄπειρα, κἂν ἄπειρος αὐτὴν χρόνος παρεσκεύασεν.", "st": "M20"}, {"sp": "N", "t": "ἡ δὲ διάνοια τοῦ τῆς σαρκὸς τέλους καὶ πέρατος λαβοῦσα τὸν ἐπιλογισμὸν καὶ τοὺς ὑπὲρ τοῦ αἰῶνος φόβους ἐκλύσασα τὸν παντελῆ βίον παρεσκεύασε, καὶ οὐθὲν ἔτι τοῦ ἀπείρου χρόνου προσεδεήθη[μεν]· ἀλλ’ οὔτε ἔφυγε τὴν ἡδονήν, οὐδ’ ἡνίκα τὴν ἐξαγωγὴν ἐκ τοῦ ζῆν τὰ πράγματα παρεσκεύαζεν, ὡς ἐλλείπουσά τι τοῦ ἀρίστου βίου κατέστρεφεν.", "st": "M21"}, {"sp": "N", "t": "Ὁ τὰ πέρατα τοῦ βίου κατειδὼς οἶδεν, ὡς εὐπόριστόν ἐστι τὸ 〈τὸ〉 ἀλγοῦν κατ’ ἔνδειαν ἐξαιροῦν καὶ τὸ τὸν ὅλον βίον παντελῆ καθιστάν· ὥστε οὐδὲν προσδεῖται πραγμάτων ἀγῶνας κεκτημένων.", "st": "M22"}, {"sp": "N", "t": "Τὸ ὑφεστηκὸς δεῖ τέλος ἐπιλογίζεσθαι καὶ πᾶσαν τὴν ἐνάργειαν, ἐφ’ ἣν τὰ δοξαζόμενα ἀνάγομεν· εἰ δὲ μή, πάντα ἀκρισίας καὶ ταραχῆς ἔσται μεστά.", "st": "M23"}, {"sp": "N", "t": "Εἰ μαχῇ πάσαις ταῖς αἰσθήσεσιν, οὐχ ἕξεις οὐδ’ ἃς ἂν φῇς αὐτῶν διεψεῦσθαι πρὸς τί ποιούμενος τὴν ἀναγωγὴν κρίνῃς.", "st": "M24"}, {"sp": "N", "t": "Εἴ τιν’ ἐκβαλεῖς ἁπλῶς αἴσθησιν καὶ μὴ διαιρήσεις τὸ δοξαζόμενον κατὰ τὸ προσμένον καὶ τὸ παρὸν ἤδη κατὰ τὴν αἴσθησιν καὶ τὰ πάθη καὶ πᾶσαν φανταστικὴν ἐπιβολὴν τῆς διανοίας, συνταράξεις καὶ τὰς λοιπὰς αἰσθήσεις τῇ ματαίῳ δόξῃ, ὥστε τὸ κριτήριον ἅπαν ἐκβαλεῖς.", "st": "M25"}, {"sp": "N", "t": "εἰ δὲ βεβαιώσεις καὶ τὸ προσμένον ἅπαν ἐν ταῖς δοξαστικαῖς ἐννοίαις καὶ τὸ μὴ τὴν ἐπιμαρτύρησιν * * οὐκ † ἐκλείψεις τὸ διεψευσμένον, ὥσ〈τε〉 τετηρηκὼς ἔσῃ πᾶσαν ἀμφισβήτησιν καὶ πᾶσαν κρίσιν τοῦ ὀρθῶς ἢ μὴ ὀρθῶς.", "st": "M26"}, {"sp": "N", "t": "Εἰ μὴ παρὰ πάντα καιρὸν ἐπανοίσεις ἕκαστον τῶν πραττομένων ἐπὶ τὸ τέλος τῆς φύσεως, ἀλλὰ προκαταστρέψεις εἴτε φυγὴν εἴτε δίωξιν ποιούμενος εἰς ἄλλο τι, οὐκ ἔσονταί σοι τοῖς λόγοις αἱ πράξεις ἀκόλουθοι. Τῶν ἐπιθυμιῶν ὅσαι μὴ ἐπ’ ἀλγοῦν ἐπανάγουσιν ἐὰν μὴ συμπληρωθῶσιν, οὐκ εἰσὶν ἀναγκαῖαι, ἀλλ’ εὐδιάχυτον τὴν ὄρεξιν ἔχουσιν, ὅταν δυσπόριστοι ἢ βλάβης ἀπεργαστικαὶ δόξωσιν εἶναι.", "st": "M27"}, {"sp": "N", "t": "Ὧν ἡ σοφία παρασκευάζεται εἰς τὴν τοῦ ὅλου βίου μακαριότητα, πολὺ μέγιστόν ἐστιν ἡ τῆς φιλίας κτῆσις.", "st": "M28"}, {"sp": "N", "t": "Ἡ αὐτὴ γνώμη θαρρεῖν τε ἐποίησεν ὑπὲρ τοῦ μηθὲν αἰώνιον εἶναι δεινὸν μηδὲ πολυχρόνιον, καὶ τὴν ἐν αὐτοῖς τοῖς ὡρισμένοις ἀσφάλειαν φιλίᾳ μάλιστα κατεῖδε συντελουμένην.", "st": "M29"}, {"sp": "N", "t": "Τῶν ἐπιθυμιῶν αἱ μέν εἰσι φυσικαὶ καὶ 〈ἀναγκαῖαι, αἱ δὲ φυσικαὶ καὶ〉 οὐκ ἀναγκαῖαι, αἱ δὲ οὔτε φυσικαὶ οὔτε ἀναγκαῖαι, ἀλλὰ παρὰ κενὴν δόξαν γινόμεναι.", "st": "M30"}, {"sp": "N", "t": "(φυσικὰς καὶ ἀναγκαίας ἡγεῖται ὁ Ἐπίκουρος τὰς ἀλγηδόνος ἀπολυούσας, ὡς ποτὸν ἐπὶ δίψους· φυσικὰς δὲ οὐκ ἀναγκαίας δὲ τάς ποικιλλούσας μόνον τὴν ἡδονήν, μὴ ὑπεξαιρουμένας δὲ τὸ ἄλγημα, ὡς πολυτελῆ σιτία· οὔτε δὲ φυσικὰς οὔτε ἀναγκαίας, ὡς στεφάνους καὶ ἀνδριάντων ἀναθέσεις.)", "st": "M30b"}, {"sp": "N", "t": "Ἐν αἷς τῶν φυσικῶν ἐπιθυμιῶν, μὴ ἐπ’ ἀλγοῦν δὲ ἐπαναγουσῶν ἐὰν μὴ συντελεσθῶσιν, ὑπάρχει ἡ σπουδὴ σύντονος, παρὰ κενὴν δόξαν αὗται γίνονται, καὶ οὐ παρὰ τὴν ἑαυτῶν φύσιν οὐ διαχέονται ἀλλὰ παρὰ τὴν τοῦ ἀνθρώπου κενοδοξίαν.", "st": "M31"}, {"sp": "N", "t": "Τὸ τῆς φύσεως δίκαιόν ἐστι σύμβολον τοῦ συμφέροντος εἰς τὸ μὴ βλάπτειν ἀλλήλους μηδὲ βλάπτεσθαι.", "st": "M33"}, {"sp": "N", "t": "Ὅσα τῶν ζῴων μὴ ἐδύνατο συνθήκας ποιεῖσθαι τὰς ὑπὲρ τοῦ μὴ βλάπτειν ἄλληλα μηδὲ βλάπτεσθαι, πρὸς ταῦτα οὐθὲν ἦν δίκαιον οὐδὲ ἄδικον· ὡσαύτως δὲ καὶ τῶν ἐθνῶν ὅσα μὴ ἐδύνατο ἢ μὴ ἐβούλετο τὰς συνθήκας ποιεῖσθαι τὰς ὑπὲρ τοῦ μὴ βλάπτειν μηδὲ βλάπτεσθαι.", "st": "M34"}, {"sp": "N", "t": "Οὐκ ἦν τι καθ’ ἑαυτὸ δικαιοσύνη, ἀλλ’ ἐν ταῖς μετ’ ἀλλήλων συστροφαῖς καθ’ ὁπηλίκους δήποτε ἀεὶ τόπους συνθήκη τις ὑπὲρ τοῦ μὴ βλάπτειν ἢ βλάπτεσθαι.", "st": "M35"}, {"sp": "N", "t": "Ἡ ἀδικία οὐ καθ’ ἑαυτὴν κακόν, ἀλλ’ ἐν τῷ κατὰ τὴν ὑποψίαν φόβῳ, εἰ μὴ λήσει τοὺς ὑπὲρ τῶν τοιούτων ἐφεστηκότας κολαστάς.", "st": "M36"}, {"sp": "N", "t": "Οὐκ ἔστι τὸν λάθρα τι ποιοῦντα ὧν συνέθεντο πρὸς ἀλλήλους εἰς τὸ μὴ βλάπτειν μηδὲ βλάπτεσθαι, πιστεύειν ὅτι λήσει, κἂν μυριάκις ἐπὶ τοῦ παρόντος λανθάνῃ. μέχρι γὰρ καταστροφῆς ἄδηλον εἰ καὶ λήσει.", "st": "M37"}, {"sp": "N", "t": "Κατὰ μὲν κοινὸν πᾶσι τὸ δίκαιον τὸ αὐτό, συμφέρον γάρ τι ἦν ἐν τῇ πρὸς ἀλλήλους κοινωνίᾳ· κατὰ δὲ τὸ ἴδιον χώρας καὶ ὅσων δήποτε αἰτίων οὐ πᾶσι συνέπεται τὸ αὐτὸ δίκαιον εἶναι.", "st": "M38"}, {"sp": "N", "t": "Τὸ μὲν ἐπιμαρτυρούμενον ὅτι συμφέρει ἐν ταῖς χρείαις τῆς πρὸς ἀλλήλους κοινωνίας τῶν νομισθέντων εἶναι δικαίων, ἔχει τὸ ἐν τοῦ δικαίου χώρᾳ εἶναι, ἐάν τε τὸ αὐτὸ πᾶσι γένηται ἐάν τε μὴ τὸ αὐτό.", "st": "M39"}, {"sp": "N", "t": "ἐὰν δὲ νόμον θῆταί τις, μὴ ἀποβαίνῃ δὲ κατὰ τὸ συμφέρον τῆς πρὸς ἀλλήλους κοινωνίας, οὐκέτι τοῦτο τὴν τοῦ δικαίου φύσιν ἔχει. κἂν μεταπίπτῃ τὸ κατὰ τὸ δίκαιον συμφέρον, χρόνον δέ τινα εἰς τὴν πρόληψιν ἐναρμόττῃ, οὐδὲν ἧττον ἐκεῖνον τὸν χρόνον ἦν δίκαιον τοῖς μὴ φωναῖς κεναῖς ἑαυτοὺς συνταράττουσιν ἀλλ’ εἰς τὰ πράγματα βλέπουσιν.", "st": "M40"}, {"sp": "N", "t": "Ἔνθα μὴ καινῶν γενομένων τῶν περιεστώτων πραγμάτων ἀνεφάνη μὴ ἁρμόττοντα εἰς τὴν πρόληψιν τὰ νομισθέντα δίκαια ἐπ’ αὐτῶν τῶν ἔργων, οὐκ ἦν ταῦτα δίκαια. ἔνθα δὲ καινῶν γενομένων τῶν πραγμάτων οὐκέτι συνέφερε τὰ αὐτὰ δίκαια κείμενα, ἐνταῦθα δὴ τότε μὲν ἦν δίκαια, ὅτε συνέφερεν εἰς τὴν πρὸς ἀλλήλους κοινωνίαν τῶν συμπολιτευομένων· ὕστερον δ’ οὐκ ἦν ἔτι δίκαια, ὅτε μὴ συνέφερεν.", "st": "M41"}, {"sp": "N", "t": "Ὁ τὸ μὴ θαρροῦν ἀπὸ τῶν ἔξωθεν ἄριστα συστησάμενος οὗτος τὰ μὲν δυνατὰ ὁμόφυλα κατεσκευάσατο, τὰ δὲ μὴ δυνατὰ οὐκ ἀλλόφυλά γε· ὅσα δὲ μηδὲ τοῦτο δυνατὸς ἦν, ἀνεπίμεικτος ἐγένετο, καὶ ἐξηρείσατο ὅσα τοῦτ’ ἐλυσιτέλει πράττειν.", "st": "M42"}, {"sp": "N", "t": "Ὅσοι τὴν δύναμιν ἔσχον τοῦ τὸ θαρρεῖν μάλιστα ἐκ τῶν ὁμορούντων παρασκευάσασθαι, οὗτοι καὶ ἐβίωσαν μετ’ ἀλλήλων ἥδιστα τὸ βεβαιότατον πίστωμα ἔχοντες, καὶ πληρεστάτην οἰκειότητα ἀπολαβόντες οὐκ ὠδύραντο ὡς πρὸς ἔλεον τὴν τοῦ τελευτήσαντος προκαταστροφήν.", "st": "M43"}], []);})();
